css:
.aps-facets {
  --aps-facets-bg: oklch(0.972 0.009 85);
  --aps-facets-ink: oklch(0.26 0.025 50);
  --aps-facets-accent: oklch(0.57 0.135 40);
  --aps-facets-clay: oklch(0.71 0.07 58);
  --aps-facets-paper: color-mix(in oklch, var(--aps-facets-bg), white 60%);
  --aps-facets-line: color-mix(in oklch, var(--aps-facets-ink) 12%, transparent);
  --aps-facets-line2: color-mix(in oklch, var(--aps-facets-ink) 22%, transparent);
  --aps-facets-mute: color-mix(in oklch, var(--aps-facets-ink) 60%, var(--aps-facets-bg));
  --aps-facets-tint: color-mix(in oklch, var(--aps-facets-accent) 11%, var(--aps-facets-bg));
  --aps-facets-shelf: color-mix(in oklch, var(--aps-facets-clay) 16%, var(--aps-facets-bg));
  --aps-facets-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-facets-out: cubic-bezier(.2, .8, .2, 1);
  --aps-facets-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --aps-facets-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--aps-facets-h, 680px);
  container-type: inline-size; container-name: aps-facets;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-facets-bg); color: var(--aps-facets-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--aps-facets-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--aps-facets-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & kbd { font: 600 10.5px/1 var(--aps-facets-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--aps-facets-line2); border-bottom-width: 2px; background: var(--aps-facets-paper); color: var(--aps-facets-mute); }

  /* ── top bar ── */
  & .aps-facets-top { display: flex; align-items: center; gap: 16px; padding: 12px 20px; border-bottom: 1px solid var(--aps-facets-line); background: var(--aps-facets-paper); }
  & .aps-facets-brand { display: flex; align-items: baseline; gap: 7px; margin-right: auto;
    & svg { width: 22px; height: 22px; align-self: center; fill: var(--aps-facets-accent); stroke: var(--aps-facets-paper); stroke-width: 1.4; }
    & b { font: italic 600 21px/1 var(--aps-facets-serif); letter-spacing: -.01em; }
    & span { font-size: 10.5px; font-weight: 650; letter-spacing: .16em; text-transform: uppercase; color: var(--aps-facets-mute); }
  }
  & .aps-facets-search { position: relative; display: flex; align-items: center; width: min(320px, 38cqi);
    & svg { position: absolute; left: 11px; width: 16px; height: 16px; fill: none; stroke: var(--aps-facets-mute); stroke-width: 2; stroke-linecap: round; pointer-events: none; }
    & input { width: 100%; height: 36px; padding: 0 36px 0 34px; border-radius: 999px; border: 1px solid var(--aps-facets-line2); background: var(--aps-facets-bg); outline: none; transition: border-color .2s, box-shadow .25s var(--aps-facets-out), background .2s; }
    & input::-webkit-search-cancel-button { display: none; }
    & input:focus { border-color: var(--aps-facets-accent); background: var(--aps-facets-paper); box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-facets-accent) 16%, transparent); }
    & kbd { position: absolute; right: 10px; transition: opacity .15s; }
    &:focus-within kbd { opacity: 0; }
  }
  & .aps-facets-bagwrap { position: relative; }
  & .aps-facets-bagbtn { position: relative; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--aps-facets-line2); background: var(--aps-facets-bg); transition: background .2s, border-color .2s;
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; }
    &:hover { background: var(--aps-facets-tint); border-color: color-mix(in oklch, var(--aps-facets-accent) 40%, transparent); }
  }
  & .aps-facets-bagn { position: absolute; top: -3px; right: -4px; min-width: 19px; height: 19px; padding: 0 5px; display: grid; place-items: center; border-radius: 10px; background: var(--aps-facets-accent); color: white; font: 700 11px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; box-shadow: 0 0 0 2px var(--aps-facets-paper); transition: scale .3s var(--aps-facets-spring), opacity .2s; }
  & .aps-facets-bagn:empty, & .aps-facets-bagn[data-zero] { scale: 0; opacity: 0; }
  & .aps-facets-bag { position: absolute; z-index: 40; right: 0; top: calc(100% + 10px); width: min(330px, calc(100cqi - 32px)); padding: 14px; border-radius: 14px; background: var(--aps-facets-paper); border: 1px solid var(--aps-facets-line); box-shadow: 0 24px 48px -16px color-mix(in oklch, var(--aps-facets-ink) 35%, transparent);
    transform-origin: top right; transition: opacity .2s, scale .35s var(--aps-facets-spring), translate .35s var(--aps-facets-spring);
    @starting-style { opacity: 0; scale: .94; translate: 0 -6px; }
    & h3 { margin: 0 0 8px; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--aps-facets-mute); }
    & ul { list-style: none; margin: 0; padding: 0; max-height: 220px; overflow: auto; overscroll-behavior: contain; }
    & li { display: grid; grid-template-columns: 44px 1fr auto auto; align-items: center; gap: 10px; padding: 6px 0; border-bottom: 1px solid var(--aps-facets-line); }
    & li svg { width: 44px; height: 38px; border-radius: 8px; background: var(--aps-facets-shelf); }
    & li b { display: block; font-size: 13px; font-weight: 600; }
    & li small { color: var(--aps-facets-mute); font-size: 12px; }
    & li span { font-variant-numeric: tabular-nums; font-weight: 600; }
    & li button { border: 0; background: none; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; color: var(--aps-facets-mute); }
    & li button:hover { background: var(--aps-facets-tint); color: var(--aps-facets-ink); }
    & li button svg { width: 14px; height: 14px; background: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
    & .aps-facets-sum { display: flex; justify-content: space-between; margin-top: 10px; font-weight: 650; font-variant-numeric: tabular-nums; }
    & .aps-facets-ship { margin: 8px 0 10px; font-size: 12px; color: var(--aps-facets-mute); }
    & .aps-facets-ship i { display: block; height: 4px; margin-top: 6px; border-radius: 4px; background: var(--aps-facets-line); overflow: hidden; }
    & .aps-facets-ship i::before { content: ""; display: block; height: 100%; width: calc(var(--p, 0) * 100%); background: var(--aps-facets-accent); border-radius: inherit; transition: width .6s var(--aps-facets-out); }
    & p.aps-facets-none { margin: 4px 0 2px; color: var(--aps-facets-mute); text-wrap: pretty; }
  }

  /* ── layout ── */
  & .aps-facets-body { position: relative; min-height: 0; display: grid; grid-template: "side main" minmax(0, 1fr) / 248px minmax(0, 1fr); }
  & .aps-facets-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--aps-facets-line); background: var(--aps-facets-bg); }
  & .aps-facets-sidehead { display: none; align-items: center; justify-content: space-between; padding: 14px 16px 10px;
    & h2 { margin: 0; font-size: 17px; font-weight: 650; letter-spacing: -.01em; }
  }
  & .aps-facets-x { width: 34px; height: 34px; border-radius: 50%; border: 0; background: var(--aps-facets-tint); display: grid; place-items: center;
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  }
  & .aps-facets-groups { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 6px 18px 18px; scrollbar-width: thin; }
  & .aps-facets-sidefoot { display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--aps-facets-line);
    & [data-show] { display: none; }
  }
  & .aps-facets-ghost { flex: 1; height: 38px; border-radius: 10px; border: 1px solid var(--aps-facets-line2); background: transparent; font-weight: 600; transition: background .2s;
    &:hover:not(:disabled) { background: var(--aps-facets-tint); }
    &:disabled { opacity: .45; cursor: default; }
  }
  & .aps-facets-cta { flex: 2; height: 38px; border-radius: 10px; border: 0; background: var(--aps-facets-ink); color: var(--aps-facets-paper); font-weight: 650; font-variant-numeric: tabular-nums; transition: background .2s, scale .25s var(--aps-facets-spring);
    &:active { scale: .97; }
  }

  /* facet groups with animated disclosure */
  & .aps-facets-grp { border-bottom: 1px solid var(--aps-facets-line); interpolate-size: allow-keywords;
    &::details-content { block-size: 0; overflow: clip; transition: block-size .35s var(--aps-facets-out), content-visibility .35s allow-discrete; }
    &[open]::details-content { block-size: auto; }
    & summary { list-style: none; display: flex; align-items: center; gap: 8px; padding: 14px 0 12px; cursor: pointer; font-size: 11.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
    & summary::-webkit-details-marker { display: none; }
    & summary span { flex: 1; }
    & summary i { font-style: normal; font-size: 11px; letter-spacing: 0; min-width: 18px; height: 18px; padding: 0 6px; border-radius: 9px; display: grid; place-items: center; background: var(--aps-facets-accent); color: white; font-variant-numeric: tabular-nums; }
    & summary i:empty { display: none; }
    & summary svg { width: 16px; height: 16px; fill: none; stroke: var(--aps-facets-mute); stroke-width: 2; stroke-linecap: round; transition: rotate .3s var(--aps-facets-out); }
    &[open] summary svg { rotate: 180deg; }
    & .aps-facets-opts { padding: 0 0 14px; display: grid; gap: 2px; }
  }
  & .aps-facets-check, & .aps-facets-switch { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; padding: 5px 6px; margin: 0 -6px; border-radius: 8px; cursor: pointer; transition: background .15s, opacity .2s;
    &:hover { background: var(--aps-facets-tint); }
    & input { margin: 0; width: 16px; height: 16px; }
    & em { font-style: normal; font-size: 12px; color: var(--aps-facets-mute); font-variant-numeric: tabular-nums; }
    &:has(input:disabled) { opacity: .38; cursor: default; background: none; }
    &:has(input:checked) span { font-weight: 600; }
  }
  & .aps-facets-switch input { appearance: none; width: 32px; height: 18px; border-radius: 9px; background: var(--aps-facets-line2); position: relative; transition: background .25s; cursor: pointer;
    &::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px rgb(0 0 0 / .25); transition: translate .35s var(--aps-facets-spring); }
    &:checked { background: var(--aps-facets-accent); }
    &:checked::after { translate: 14px 0; }
  }
  & .aps-facets-swatches { display: grid; grid-template-columns: 1fr; gap: 1px; padding-bottom: 14px; }
  & .aps-facets-sw { display: flex; align-items: center; gap: 10px; padding: 4px 6px 4px 4px; margin: 0 -6px 0 -4px; border-radius: 9px; border: 1px solid transparent; background: none; text-align: left; font-size: 14px; transition: background .15s, border-color .2s, opacity .2s;
    & i { flex: none; width: 20px; height: 20px; border-radius: 50%; background: radial-gradient(circle at 34% 30%, color-mix(in oklch, var(--g), white 38%), var(--g) 55%, color-mix(in oklch, var(--g), black 22%)); box-shadow: inset 0 0 0 1px rgb(0 0 0 / .08); position: relative; transition: scale .35s var(--aps-facets-spring); }
    & i::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; border: 2px solid var(--aps-facets-ink); opacity: 0; scale: .8; transition: opacity .2s, scale .35s var(--aps-facets-spring); }
    & span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & em { font-style: normal; font-size: 12px; color: var(--aps-facets-mute); font-variant-numeric: tabular-nums; }
    &:hover:not(:disabled) { background: var(--aps-facets-tint); }
    &:hover:not(:disabled) i { scale: 1.08; }
    &[aria-pressed="true"] { border-color: var(--aps-facets-line2); background: var(--aps-facets-paper); }
    &[aria-pressed="true"] i::after { opacity: 1; scale: 1; }
    &[aria-pressed="true"] span { font-weight: 600; }
    &:disabled { opacity: .35; cursor: default; }
  }
  & .aps-facets-pills { display: flex; flex-wrap: wrap; gap: 6px; padding-bottom: 14px; }
  & .aps-facets-pill { height: 30px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-facets-line2); background: transparent; font-size: 13px; display: inline-flex; align-items: center; gap: 6px; transition: background .2s, color .2s, border-color .2s;
    & em { font-style: normal; font-size: 11.5px; opacity: .65; font-variant-numeric: tabular-nums; }
    &:hover:not(:disabled) { border-color: var(--aps-facets-ink); }
    &[aria-pressed="true"] { background: var(--aps-facets-ink); border-color: var(--aps-facets-ink); color: var(--aps-facets-paper); }
    &:disabled { opacity: .35; cursor: default; }
  }

  /* price: histogram behind a dual range */
  & .aps-facets-price { padding: 2px 0 16px; }
  & .aps-facets-hist { display: flex; align-items: flex-end; gap: 2px; height: 46px; padding: 0 8px;
    & i { flex: 1; height: calc(var(--h) * 100%); min-height: 2px; border-radius: 2px 2px 0 0; background: var(--aps-facets-accent); opacity: .85; transition: height .45s var(--aps-facets-out), opacity .2s, background .2s; }
    & i.is-out { background: var(--aps-facets-line2); opacity: .7; }
  }
  & .aps-facets-range { position: relative; height: 22px; margin-top: -1px;
    &::before { content: ""; position: absolute; left: 8px; right: 8px; top: 10px; height: 2px; border-radius: 2px; background: var(--aps-facets-line2); }
    & .aps-facets-fill { position: absolute; top: 10px; height: 2px; background: var(--aps-facets-ink); left: calc(8px + var(--a) * (100% - 16px)); right: calc(8px + (1 - var(--b)) * (100% - 16px)); }
    & input { position: absolute; inset: 0; width: 100%; margin: 0; appearance: none; background: none; pointer-events: none; height: 22px; }
    & input::-webkit-slider-runnable-track { height: 22px; background: none; }
    & input::-webkit-slider-thumb { appearance: none; pointer-events: auto; width: 18px; height: 18px; margin-top: 2px; border-radius: 50%; background: var(--aps-facets-paper); border: 2px solid var(--aps-facets-ink); box-shadow: 0 2px 6px -1px rgb(0 0 0 / .25); cursor: grab; transition: scale .3s var(--aps-facets-spring); }
    & input::-moz-range-thumb { pointer-events: auto; width: 14px; height: 14px; border-radius: 50%; background: var(--aps-facets-paper); border: 2px solid var(--aps-facets-ink); cursor: grab; }
    & input::-moz-range-track { background: none; }
    & input:active::-webkit-slider-thumb { scale: 1.18; cursor: grabbing; }
    & input:focus-visible { outline: none; }
    & input:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-facets-accent) 35%, transparent); }
  }
  & .aps-facets-pr { display: flex; justify-content: space-between; margin-top: 6px; font: 600 12.5px/1 var(--aps-facets-mono); font-variant-numeric: tabular-nums; color: var(--aps-facets-mute); }

  /* ── main column ── */
  & .aps-facets-main { grid-area: main; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scroll-padding-top: 64px; }
  & .aps-facets-hero { padding: clamp(16px, 2.4cqi, 28px) clamp(16px, 2.4cqi, 28px) 6px;
    & h1 { margin: 2px 0 6px; font: 500 clamp(24px, 3.2cqi, 38px)/1.05 var(--aps-facets-serif); letter-spacing: -.02em; text-wrap: balance; }
    & .aps-facets-lede { margin: 0; max-width: 60ch; color: var(--aps-facets-mute); text-wrap: pretty; }
  }
  & .aps-facets-crumb { margin: 0; font-size: 11px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--aps-facets-mute);
    & span { margin: 0 4px; opacity: .5; }
  }
  & .aps-facets-bar { position: sticky; top: 0; z-index: 5; display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; padding: 12px clamp(16px, 2.4cqi, 28px); background: color-mix(in oklch, var(--aps-facets-bg) 92%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid transparent; }
  @supports (animation-timeline: scroll()) {
    & .aps-facets-bar { animation: aps-facets-stick linear both; animation-timeline: scroll(nearest block); animation-range: 0 90px; }
  }
  & .aps-facets-fbtn { display: none; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-facets-line2); background: var(--aps-facets-paper); font-weight: 600; font-size: 13px;
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
    & span { min-width: 18px; height: 18px; border-radius: 9px; padding: 0 5px; background: var(--aps-facets-accent); color: white; font-size: 11px; display: grid; place-items: center; }
    & span:empty { display: none; }
  }
  & .aps-facets-chips { display: flex; flex-wrap: wrap; gap: 6px; flex: 1 1 260px; min-width: 0; }
  & .aps-facets-chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 6px 0 10px; border-radius: 999px; border: 0; background: var(--aps-facets-tint); font-size: 12.5px; font-weight: 600; color: color-mix(in oklch, var(--aps-facets-accent), var(--aps-facets-ink) 45%); transition: background .2s, scale .3s var(--aps-facets-spring);
    @starting-style { scale: .6; opacity: 0; }
    & i { width: 10px; height: 10px; border-radius: 50%; background: var(--g); box-shadow: inset 0 0 0 1px rgb(0 0 0 / .1); }
    & svg { width: 16px; height: 16px; padding: 3px; border-radius: 50%; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; transition: background .2s; }
    &:hover svg { background: color-mix(in oklch, var(--aps-facets-accent) 22%, transparent); }
  }
  & .aps-facets-chips > .aps-facets-clear { border: 0; background: none; font-size: 12.5px; font-weight: 600; color: var(--aps-facets-mute); text-decoration: underline; text-underline-offset: 3px; padding: 0 4px; }
  & .aps-facets-count { margin: 0 0 0 auto; font-size: 13px; color: var(--aps-facets-mute); font-variant-numeric: tabular-nums; white-space: nowrap;
    & b { color: var(--aps-facets-ink); font-weight: 650; }
  }
  & .aps-facets-sort { position: relative; display: flex; align-items: center;
    & span { position: absolute; left: 12px; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--aps-facets-mute); pointer-events: none; }
    & select { appearance: none; height: 34px; padding: 0 32px 0 50px; border-radius: 999px; border: 1px solid var(--aps-facets-line2); background: var(--aps-facets-paper); font-size: 13px; font-weight: 600; cursor: pointer; }
    & svg { position: absolute; right: 10px; width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; pointer-events: none; }
  }
  & .aps-facets-seg { display: flex; padding: 3px; gap: 2px; border-radius: 999px; background: color-mix(in oklch, var(--aps-facets-ink) 7%, transparent);
    & button { width: 30px; height: 28px; border: 0; border-radius: 999px; background: none; display: grid; place-items: center; color: var(--aps-facets-mute); transition: background .25s var(--aps-facets-out), color .2s; }
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
    & [aria-checked="true"] { background: var(--aps-facets-paper); color: var(--aps-facets-ink); box-shadow: 0 1px 3px rgb(0 0 0 / .12); }
  }

  /* ── product grid ── */
  & .aps-facets-grid { list-style: none; margin: 0; padding: 8px clamp(16px, 2.4cqi, 28px) 20px; display: grid; grid-template-columns: repeat(auto-fill, minmax(184px, 1fr)); gap: 22px 18px; }
  & .aps-facets-card { position: relative; display: grid; grid-template-rows: auto 1fr; gap: 10px; border-radius: 12px; cursor: default; outline-offset: 4px;
    &.is-in { animation: aps-facets-in .6s var(--aps-facets-spring) calc(var(--i, 0) * 32ms) both; }
  }
  & .aps-facets-thumb { position: relative; aspect-ratio: 5 / 4; border-radius: 12px; overflow: hidden;
    background: radial-gradient(120% 90% at 50% 20%, var(--aps-facets-paper), var(--aps-facets-shelf) 70%);
    &::after { content: ""; position: absolute; inset: auto 0 0; height: 24%; background: linear-gradient(color-mix(in oklch, var(--aps-facets-clay) 10%, transparent), color-mix(in oklch, var(--aps-facets-clay) 18%, transparent)); pointer-events: none; }
    & svg { position: relative; z-index: 1; width: 100%; height: 100%; }
  }
  & .aps-facets-art {
    & .ft { fill: var(--aps-facets-clay); }
    & .gz { fill: var(--g); }
    & .hd { fill: none; stroke: var(--g); stroke-width: 7; stroke-linecap: round; }
    & .rim { fill: color-mix(in oklch, var(--g), black 30%); }
    & .in { fill: color-mix(in oklch, var(--g), black 12%); }
    & .sp { fill: none; stroke: white; stroke-linecap: round; stroke-width: 3; opacity: .55; }
    & .sp.satin { opacity: .22; stroke-width: 6; }
    & .sh { fill: color-mix(in oklch, var(--aps-facets-ink) 30%, transparent); transform-box: fill-box; transform-origin: center; transition: scale .5s var(--aps-facets-spring), opacity .4s; }
    & .obj { transition: translate .5s var(--aps-facets-spring); }
