  const cols = Math.max(1, list.filter(n => n.offsetTop === top).length);
  const d = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: cols, ArrowUp: -cols, Home: -i, End: list.length - 1 - i }[e.key];
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); addToBag(card.dataset.id); return true; }
  if (d === undefined) return false;
  e.preventDefault();
  const n = list[Math.max(0, Math.min(list.length - 1, i + d))];
  focusCard(n);
  return true;
}
function focusCard(n) {
  if (!n) return;
  focusId = n.dataset.id;
  shown.forEach(id => { nodes.get(id).tabIndex = id === focusId ? 0 : -1; });
  n.focus({ preventScroll: true });
  const pr = main.getBoundingClientRect(), r = n.getBoundingClientRect(), bar = $('.aps-facets-bar').offsetHeight;
  if (r.top < pr.top + bar + 8) main.scrollBy({ top: r.top - pr.top - bar - 12, behavior: RM.matches ? 'auto' : 'smooth' });
  else if (r.bottom > pr.bottom - 8) main.scrollBy({ top: r.bottom - pr.bottom + 16, behavior: RM.matches ? 'auto' : 'smooth' });
}
grid.addEventListener('focusin', e => { const c = e.target.closest('.aps-facets-card'); if (c) { focusId = c.dataset.id; shown.forEach(id => { nodes.get(id).tabIndex = id === focusId ? 0 : -1; }); } });

root.addEventListener('keydown', e => {
  const typing = e.target.matches('input[type="search"], select');
  if (e.key === 'Escape') {
    if (bagOpen) { setBag(false); bagBtn.focus({ preventScroll: true }); return; }
    if (sheet) { setSheet(false); $('.aps-facets-fbtn').focus({ preventScroll: true }); return; }
    if (e.target === search && search.value) { e.preventDefault(); search.value = ''; F.q = ''; render(true); return; }
    return;
  }
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && !typing) { e.preventDefault(); undo(); return; }
  if (e.target === search && e.key === 'Enter') { e.preventDefault(); search.blur(); focusCard(nodes.get(shown[0])); return; }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  if (rove(e) || gridNav(e)) return;
  if (e.target.matches('input')) return;
  const k = e.key.toLowerCase();
  if (e.key === '/') { e.preventDefault(); search.focus({ preventScroll: true }); search.select(); }
  else if (k === 'g') setView(view === 'grid' ? 'list' : 'grid');
  else if (k === 'f') { if (narrow) setSheet(!sheet); else { const f = $('.aps-facets-groups input, .aps-facets-groups button'); if (f) f.focus({ preventScroll: true }); } }
});

/* first paint: stagger cards in with --i */
render(false);
renderBag();
setSheet(false);
if (!RM.matches) shown.slice(0, 12).forEach((id, i) => { const n = nodes.get(id); n.style.setProperty('--i', i); n.classList.add('is-in'); n.addEventListener('animationend', () => n.classList.remove('is-in'), { once: true }); });

