.aps-pdp {
  --aps-pdp-bg: oklch(0.175 0.006 70);
  --aps-pdp-fg: oklch(0.94 0.012 85);
  --aps-pdp-accent: oklch(0.79 0.105 78);
  --aps-pdp-warn: oklch(0.72 0.15 42);
  --aps-pdp-panel: color-mix(in oklch, var(--aps-pdp-bg), white 4.5%);
  --aps-pdp-raise: color-mix(in oklch, var(--aps-pdp-bg), white 9%);
  --aps-pdp-line: color-mix(in oklch, var(--aps-pdp-fg) 11%, transparent);
  --aps-pdp-line2: color-mix(in oklch, var(--aps-pdp-fg) 22%, transparent);
  --aps-pdp-mute: color-mix(in oklch, var(--aps-pdp-fg) 56%, var(--aps-pdp-bg));
  --aps-pdp-ease: cubic-bezier(.2, .8, .2, 1);
  --aps-pdp-cam: cubic-bezier(.65, 0, .2, 1);
  --aps-pdp-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-pdp-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--aps-pdp-h, 680px);
  container-type: inline-size; container-name: aps-pdp;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-pdp-bg); color: var(--aps-pdp-fg);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--aps-pdp-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--aps-pdp-accent); outline-offset: 3px; border-radius: 8px; }
  & kbd { font: 600 10px/1 var(--aps-pdp-mono); padding: 3px 5px 2px; border-radius: 4px; background: color-mix(in oklch, var(--aps-pdp-fg) 10%, transparent); color: var(--aps-pdp-mute); box-shadow: inset 0 -1px 0 rgb(0 0 0 / .45); }

  & .aps-pdp-top { display: flex; align-items: center; gap: 18px; padding: 12px 22px; border-bottom: 1px solid var(--aps-pdp-line); }
  & .aps-pdp-brand { display: flex; align-items: center; gap: 9px;
    & svg { width: 22px; height: 22px; fill: none; stroke: var(--aps-pdp-accent); stroke-width: 1.6; stroke-linecap: round; }
    & b { font-size: 13px; font-weight: 700; letter-spacing: .32em; text-transform: uppercase; }
  }
  & .aps-pdp-crumb { margin: 0 auto 0 12px; font-size: 12.5px; color: var(--aps-pdp-mute);
    & span { margin: 0 6px; opacity: .5; } & b { color: var(--aps-pdp-fg); font-weight: 600; }
  }
  & .aps-pdp-bagwrap { position: relative; }
  & .aps-pdp-bagbtn { position: relative; width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--aps-pdp-line2); background: transparent; display: grid; place-items: center; transition: background .2s;
    &:hover { background: var(--aps-pdp-raise); }
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; }
    & span { position: absolute; top: -3px; right: -4px; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 10px; display: grid; place-items: center; background: var(--aps-pdp-accent); color: var(--aps-pdp-bg); font: 700 11px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; transition: scale .35s var(--aps-pdp-spring); }
    & span:empty { scale: 0; }
  }
  & .aps-pdp-added { position: absolute; z-index: 50; right: 0; top: calc(100% + 10px); width: min(320px, calc(100cqi - 28px)); display: grid; grid-template-columns: 64px 1fr; gap: 4px 12px; padding: 12px; border-radius: 14px; background: var(--aps-pdp-raise); border: 1px solid var(--aps-pdp-line); box-shadow: 0 30px 60px -20px rgb(0 0 0 / .7);
    transform-origin: top right; transition: opacity .25s, scale .45s var(--aps-pdp-spring), translate .45s var(--aps-pdp-spring);
    @starting-style { opacity: 0; scale: .9; translate: 0 -8px; }
    & svg { grid-row: span 3; width: 64px; height: 64px; border-radius: 10px; background: var(--aps-pdp-bg); }
    & small { font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--aps-pdp-accent); }
    & b { font-weight: 600; }
    & span { font-size: 12.5px; color: var(--aps-pdp-mute); font-variant-numeric: tabular-nums; }
  }

  & .aps-pdp-body { min-height: 0; display: grid; grid-template: "gallery buy" minmax(0, 1fr) / minmax(0, 1.22fr) minmax(320px, 1fr); }

  /* ── gallery: one 3D object, four camera positions ── */
  & .aps-pdp-gallery { grid-area: gallery; min-height: 0; display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 14px; padding: 18px 0 18px 18px; }
  & .aps-pdp-thumbs { display: flex; flex-direction: column; gap: 10px; }
  & .aps-pdp-thumb { position: relative; width: 76px; aspect-ratio: 1; padding: 0; border-radius: 12px; border: 1px solid var(--aps-pdp-line); background: radial-gradient(circle at 50% 40%, var(--aps-pdp-raise), var(--aps-pdp-panel)); overflow: hidden; transition: border-color .25s, translate .35s var(--aps-pdp-spring);
    & > svg { width: 100%; height: 100%; }
    & .aps-pdp-tilt { transform: perspective(300px) rotateY(-34deg) rotateX(10deg); }
    &:hover { translate: 2px 0; }
    &[aria-selected="true"] { border-color: var(--aps-pdp-accent); }
    &[aria-selected="true"]::after { content: ""; position: absolute; left: -1px; top: 18%; bottom: 18%; width: 3px; border-radius: 0 3px 3px 0; background: var(--aps-pdp-accent); }
  }
  & .aps-pdp-stage { position: relative; min-height: 0; border-radius: 18px; overflow: hidden; cursor: zoom-in;
    background: radial-gradient(70% 60% at 50% 42%, color-mix(in oklch, var(--aps-pdp-accent) 10%, var(--aps-pdp-raise)), var(--aps-pdp-panel) 62%, var(--aps-pdp-bg));
    &.is-zoom { cursor: zoom-out; }
  }
  & .aps-pdp-loupe { position: absolute; inset: 0; display: grid; place-items: center; perspective: 1400px; transition: scale .55s var(--aps-pdp-ease); transform-origin: var(--zx, 50%) var(--zy, 50%); }
  & .aps-pdp-stage.is-zoom .aps-pdp-loupe { scale: 1.9; transition: scale .55s var(--aps-pdp-ease), transform-origin .12s linear; }
  & .aps-pdp-obj { position: relative; height: 88%; aspect-ratio: 1; max-width: 92%; transform-style: preserve-3d; transition: transform 1s var(--aps-pdp-cam); }
  & .aps-pdp-face { position: absolute; inset: 0; backface-visibility: hidden; -webkit-backface-visibility: hidden;
    & > svg { width: 100%; height: 100%; overflow: visible; filter: drop-shadow(0 26px 30px rgb(0 0 0 / .55)); }
  }
  & .aps-pdp-back { transform: rotateY(180deg); }
  & .aps-pdp-shadow { position: absolute; left: 50%; top: 50%; width: 44%; height: 12%; translate: -50% 330%; border-radius: 50%; background: radial-gradient(closest-side, rgb(0 0 0 / .55), transparent); filter: blur(6px); transition: scale 1s var(--aps-pdp-cam), opacity .6s; }
  & .aps-pdp-stage[data-view="angle"] .aps-pdp-obj { transform: rotateY(-36deg) rotateX(14deg) translateZ(-40px); }
  & .aps-pdp-stage[data-view="angle"] .aps-pdp-shadow { scale: .75 1.2; }
  & .aps-pdp-stage[data-view="back"] .aps-pdp-obj { transform: rotateY(180deg); }
  & .aps-pdp-stage[data-view="detail"] .aps-pdp-obj { transform: scale(2.5) translate(-12%, 0); }
  & .aps-pdp-stage[data-view="detail"] .aps-pdp-shadow { opacity: 0; }
  & .aps-pdp-vlabel { position: absolute; left: 14px; bottom: 12px; margin: 0; padding: 5px 10px; border-radius: 999px; background: color-mix(in oklch, var(--aps-pdp-bg) 70%, transparent); backdrop-filter: blur(8px); font-size: 12px; color: var(--aps-pdp-mute); font-variant-numeric: tabular-nums;
    & b { color: var(--aps-pdp-fg); font-weight: 600; margin-right: 6px; }
  }
  & .aps-pdp-vkeys { position: absolute; right: 14px; bottom: 12px; margin: 0; padding: 5px 10px; border-radius: 999px; background: color-mix(in oklch, var(--aps-pdp-bg) 70%, transparent); backdrop-filter: blur(8px); display: flex; align-items: center; gap: 4px; font-size: 11.5px; color: var(--aps-pdp-mute);
    & kbd:nth-of-type(3) { margin-left: 8px; }
  }
  & .aps-pdp-nav { position: absolute; top: 50%; translate: 0 -50%; width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--aps-pdp-line2); background: color-mix(in oklch, var(--aps-pdp-bg) 60%, transparent); backdrop-filter: blur(8px); display: grid; place-items: center; opacity: 0; transition: opacity .25s, scale .3s var(--aps-pdp-spring);
    &[data-step="-1"] { left: 14px; } &[data-step="1"] { right: 14px; }
    & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    &:active { scale: .92; }
  }
  & .aps-pdp-stage:hover .aps-pdp-nav, & .aps-pdp-nav:focus-visible { opacity: 1; }

  /* watch art */
  & .aps-pdp-w {
    & .lum { fill: var(--lum); }
    & .ink { fill: var(--ink); }
    & .tick { stroke: var(--ink); }
    & .hand { transform-box: view-box; transform-origin: 200px 200px; animation: aps-pdp-spin var(--p) linear infinite; animation-delay: var(--d); }
    & .sec { animation-timing-function: steps(480); }
    & .rotor { transform-box: view-box; transform-origin: 200px 200px; animation: aps-pdp-rotor 7s cubic-bezier(.45, 0, .25, 1) infinite alternate; }
    & .bal { transform-box: fill-box; transform-origin: center; animation: aps-pdp-bal .25s cubic-bezier(.4, 0, .6, 1) infinite alternate; }
  }
  &.is-off .aps-pdp-w .hand, &.is-off .aps-pdp-w .rotor, &.is-off .aps-pdp-w .bal { animation-play-state: paused; }

  /* ── buy box ── */
  & .aps-pdp-buy { grid-area: buy; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 26px clamp(18px, 3cqi, 40px) 28px clamp(18px, 2.6cqi, 34px);
    & h1 { margin: 6px 0 8px; font-size: clamp(28px, 3.6cqi, 42px); line-height: 1.02; font-weight: 600; letter-spacing: -.028em; text-wrap: balance; }
    & h1 span { color: var(--aps-pdp-mute); font-weight: 400; font-variant-numeric: tabular-nums; }
  }
  & .aps-pdp-kicker { margin: 0; font-size: 11px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--aps-pdp-accent);
    & span { font-family: var(--aps-pdp-mono); letter-spacing: .04em; }
  }
  & .aps-pdp-rating { display: inline-flex; align-items: center; gap: 8px; padding: 2px 0; border: 0; background: none; font-size: 13px; color: var(--aps-pdp-mute);
    & b { color: var(--aps-pdp-fg); font-weight: 600; }
    & span:last-child { text-decoration: underline; text-decoration-color: var(--aps-pdp-line2); text-underline-offset: 3px; }
    &:hover span:last-child { text-decoration-color: currentColor; }
  }
  & .aps-pdp-stars { display: flex; gap: 1px;
    & svg { width: 13px; height: 13px; fill: var(--aps-pdp-accent); }
    & svg:last-child { fill: color-mix(in oklch, var(--aps-pdp-accent) 70%, var(--aps-pdp-bg)); }
  }
  & .aps-pdp-price { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 12px; margin: 14px 0 6px;
    & b { font-size: 26px; font-weight: 500; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
    & span { font-size: 13px; color: var(--aps-pdp-mute); font-variant-numeric: tabular-nums; }
  }
  & .aps-pdp-opts { display: grid; gap: 16px; margin: 18px 0 14px; padding-top: 18px; border-top: 1px solid var(--aps-pdp-line); }
  & .aps-pdp-opts fieldset { margin: 0; padding: 0; border: 0; min-width: 0; }
  & .aps-pdp-opts legend { display: flex; align-items: baseline; gap: 8px; width: 100%; padding: 0; margin-bottom: 9px; font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--aps-pdp-mute);
    & span { font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--aps-pdp-fg); }
  }
  & .aps-pdp-link { margin-left: auto; border: 0; background: none; padding: 0; font-size: 12.5px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--aps-pdp-accent); text-decoration: underline; text-underline-offset: 3px; }
  & .aps-pdp-row { display: flex; flex-wrap: wrap; gap: 8px; }
  & .aps-pdp-opt { position: relative; cursor: pointer;
    & input { position: absolute; opacity: 0; pointer-events: none; }
    & > span { position: relative; display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 14px; border-radius: 10px; border: 1px solid var(--aps-pdp-line2); font-size: 13px; font-weight: 500; transition: border-color .2s, background .2s, color .2s; }
    & em { font-style: normal; font-size: 11.5px; color: var(--aps-pdp-mute); font-variant-numeric: tabular-nums; }
    & i { width: 18px; height: 18px; border-radius: 50%; background: var(--sw); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .18), inset 0 -3px 5px rgb(0 0 0 / .25); }
    &:hover > span { border-color: color-mix(in oklch, var(--aps-pdp-fg) 45%, transparent); }
    &:has(input:checked) > span { border-color: var(--aps-pdp-accent); background: color-mix(in oklch, var(--aps-pdp-accent) 9%, transparent); }
    &:has(input:focus-visible) > span { outline: 2px solid var(--aps-pdp-accent); outline-offset: 2px; }
    &[data-out] > span { color: var(--aps-pdp-mute); background-image: linear-gradient(to top right, transparent calc(50% - .7px), var(--aps-pdp-line2) 50%, transparent calc(50% + .7px)); }
  }
  & .aps-pdp-opt.is-dot > span { width: 40px; padding: 0; justify-content: center; border-radius: 50%;
    & i { width: 28px; height: 28px; }
  }
  & .aps-pdp-stock { display: flex; align-items: center; gap: 8px; min-height: 22px; margin: 0 0 12px; font-size: 13px; color: var(--aps-pdp-mute); text-wrap: pretty;
    &::before { content: ""; flex: none; width: 8px; height: 8px; border-radius: 50%; background: oklch(0.78 0.14 150); box-shadow: 0 0 0 4px color-mix(in oklch, oklch(0.78 0.14 150) 18%, transparent); }
    &[data-s="low"]::before { background: var(--aps-pdp-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-pdp-accent) 20%, transparent); }
    &[data-s="out"]::before { background: var(--aps-pdp-warn); box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-pdp-warn) 20%, transparent); }
    & b { color: var(--aps-pdp-fg); font-weight: 600; }
  }
  & .aps-pdp-ctas { display: grid; gap: 8px; }
  & .aps-pdp-add { position: relative; display: flex; align-items: center; justify-content: center; gap: 10px; height: 50px; border: 0; border-radius: 12px; background: var(--aps-pdp-accent); color: oklch(0.2 0.02 70); font-size: 15px; font-weight: 650; overflow: hidden; transition: background .25s, scale .25s var(--aps-pdp-spring);
    & kbd { background: rgb(0 0 0 / .12); color: inherit; box-shadow: none; }
    &::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, rgb(255 255 255 / .35) 50%, transparent 70%); translate: -100% 0; }
    &:hover::after { translate: 100% 0; transition: translate .8s var(--aps-pdp-ease); }
    &:active { scale: .98; }
    &.is-out { background: var(--aps-pdp-raise); color: var(--aps-pdp-fg); }
    &.is-out kbd { display: none; }
    &.is-done { background: oklch(0.78 0.14 150); }
  }
  & .aps-pdp-alt { height: 44px; border-radius: 12px; border: 1px dashed var(--aps-pdp-line2); background: none; font-size: 13px; color: var(--aps-pdp-fg); transition: border-color .2s, background .2s;
    &:hover { border-color: var(--aps-pdp-accent); background: color-mix(in oklch, var(--aps-pdp-accent) 7%, transparent); }
    & b { color: var(--aps-pdp-accent); font-weight: 600; }
  }
  & .aps-pdp-perks { list-style: none; margin: 18px 0 8px; padding: 0; display: grid; gap: 8px; font-size: 13px; color: var(--aps-pdp-mute);
    & li { display: flex; align-items: center; gap: 10px; }
    & svg { flex: none; width: 18px; height: 18px; fill: none; stroke: var(--aps-pdp-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  }
  & .aps-pdp-acc { border-top: 1px solid var(--aps-pdp-line); interpolate-size: allow-keywords;
    &:last-of-type { border-bottom: 1px solid var(--aps-pdp-line); }
    &::details-content { block-size: 0; overflow: clip; transition: block-size .4s var(--aps-pdp-ease), content-visibility .4s allow-discrete; }
    &[open]::details-content { block-size: auto; }
    & summary { list-style: none; display: flex; align-items: center; justify-content: space-between; padding: 14px 0; cursor: pointer; font-weight: 600; }
    & summary::-webkit-details-marker { display: none; }
    & summary svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; transition: rotate .4s var(--aps-pdp-spring); }
    &[open] summary svg { rotate: 45deg; }
    & > p { margin: 0 0 16px; color: var(--aps-pdp-mute); text-wrap: pretty; }
  }
  & .aps-pdp-specs { display: grid; grid-template-columns: auto 1fr; gap: 8px 18px; margin: 0 0 16px; font-size: 13px;
    & dt { color: var(--aps-pdp-mute); }
    & dd { margin: 0; font-variant-numeric: tabular-nums; }
    & dd.is-new { animation: aps-pdp-flash 1.2s var(--aps-pdp-ease); }
  }
  & .aps-pdp-revs { display: grid; gap: 6px; padding-bottom: 16px; font-size: 12.5px;
    & div { display: grid; grid-template-columns: 26px 1fr 34px; align-items: center; gap: 10px; font-variant-numeric: tabular-nums; color: var(--aps-pdp-mute); }
    & i { height: 6px; border-radius: 3px; background: var(--aps-pdp-line); overflow: hidden; }
    & i::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--aps-pdp-accent); border-radius: inherit; transform-origin: left; }
    & blockquote { margin: 10px 0 0; padding: 12px 14px; border-radius: 12px; background: var(--aps-pdp-panel); color: var(--aps-pdp-fg); font-size: 13px; text-wrap: pretty; }
    & cite { display: block; margin-top: 6px; font-style: normal; font-size: 12px; color: var(--aps-pdp-mute); }
  }
  & .aps-pdp-acc[open] .aps-pdp-revs i::before { animation: aps-pdp-grow .9s var(--aps-pdp-ease) both; }

