stage.addEventListener('pointerdown', e => { swiped = false; if (e.pointerType !== 'mouse') sx = e.clientX; });
stage.addEventListener('pointerup', e => { if (sx != null && Math.abs(e.clientX - sx) > 40 && !zoom) { swiped = true; setView(view + (e.clientX < sx ? 1 : -1)); } sx = null; });

/* ── price tween ── */
let tw = 0;
function tweenPrice(to) {
  const from = shownPrice, el = $('[data-price]'), t0 = performance.now();
  cancelAnimationFrame(tw);
  if (RM.matches || from === to) { shownPrice = to; el.textContent = usd(to); return; }
  const step = now => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / 520), e = 1 - Math.pow(1 - k, 4);
    shownPrice = Math.round(from + (to - from) * e);
    el.textContent = usd(shownPrice);
    if (k < 1) tw = requestAnimationFrame(step);
  };
  tw = requestAnimationFrame(step);
}

/* ── the nearest in-stock configuration: fewest, cheapest attribute changes ── */
function nearest() {
  let best = null;
  Object.keys(CASES).forEach(c => Object.keys(DIALS).forEach(d => Object.keys(SIZES).forEach(s => {
    if (!stock(c, d, s)) return;
    const cost = (c !== V.case) * 1.3 + (d !== V.dial) * 1.1 + (+s !== +V.size) * (1 + Math.abs(s - V.size) / 10);
    if (!best || cost < best.cost) best = { c, d, s: +s, cost };
  })));
  return best;
}

/* ── render ── */
let lastSpecs = {};
function render(prev) {
  const S = SIZES[V.size], n = stock(V.case, V.dial, V.size), price = priceOf(V);
  /* options: checked state, and which choices are impossible given the others */
  Object.keys(OPTS).forEach(g => $$('fieldset[data-g="' + g + '"] .aps-pdp-opt').forEach(l => {
    const k = l.dataset.k, inp = l.querySelector('input');
    inp.checked = String(V[g]) === k;
    const test = Object.assign({}, V, { [g]: g === 'size' ? +k : k });
    const ok = g === 'strap' || stock(test.case, test.dial, test.size) > 0;
    l.toggleAttribute('data-out', !ok);
    inp.setAttribute('aria-label', OPTS[g].find(o => o[0] === k)[1] + (ok ? '' : ', sold out with current choices'));
  }));
  $('[data-pick="case"]').textContent = CASES[V.case].n;
  $('[data-pick="dial"]').textContent = DIALS[V.dial].n;
  $('[data-pick="size"]').textContent = S.l2l + ' mm lug to lug';
  $('[data-pick="strap"]').textContent = strapName(V);
  $('[data-ref]').textContent = refOf(V);
  $('[data-size-title]').textContent = V.size;
  tweenPrice(price);
  $('[data-split]').textContent = 'or 4 interest-free payments of ' + usd(Math.round(price / 4 * 100) / 100);
  $('[data-price2]').textContent = usd(price);
  $('[data-cfg2]').textContent = cfg(V);

  const st = $('[data-stock]'), add = $('.aps-pdp-add[data-act="add"]'), alt = $('[data-act="nearest"]');
