    add.classList.add('is-out'); $('[data-addlabel]').textContent = on ? 'We’ll email you when it’s back' : 'Notify me when available';
    alt.hidden = !b;
    if (b) { alt.dataset.to = JSON.stringify(b); alt.innerHTML = 'In stock as <b>' + [b.c !== V.case && CASES[b.c].n, b.d !== V.dial && DIALS[b.d].n, b.s !== +V.size && b.s + ' mm'].filter(Boolean).join(' / ') + '</b> · Switch'; }
  } else {
    st.dataset.s = n <= 3 ? 'low' : 'in';
    st.innerHTML = n <= 3 ? '<span><b>Only ' + n + ' left</b> in this configuration · ships in 2 days</span>' : '<span><b>In stock</b> · ships from the Vos workshop in 2 days</span>';
