    Reference: refOf(V), Movement: 'AV-31 automatic, 28,800 vph, 42 h reserve', Case: V.size + ' × ' + S.h + ' mm, ' + CASES[V.case].n.toLowerCase(),
    'Lug width': S.lugmm + ' mm', Crystal: 'Domed sapphire, inner anti-reflective', 'Water resistance': '100 m, screw-down crown',
