function choose(g, k) {
  const was = Object.assign({}, V);
  V[g] = g === 'size' ? +k : k;
  if (JSON.stringify(was) === JSON.stringify(V)) return;
  past.push({ v: was });
  /* changing the case or dial is easiest to judge from the front */
  if ((g === 'dial' || g === 'case') && view === 2) setView(0);
  if (g === 'strap' && view === 3) setView(0);
  render(true);
}

/* ── bag ── */
const bagBtn = $('.aps-pdp-bagbtn'), addedEl = $('.aps-pdp-added');
let at = 0;
function renderBag() {
  $('[data-bagn]').textContent = bag.length || '';
  bagBtn.setAttribute('aria-label', 'Bag, ' + bag.length + ' item' + (bag.length === 1 ? '' : 's') + (bag.length ? ', ' + usd(bag.reduce((s, b) => s + priceOf(b), 0)) : ''));
}
function addToBag() {
  if (!stock(V.case, V.dial, V.size)) {
    const k = refOf(V);
    if (notify.has(k)) notify.delete(k); else notify.add(k);
    render(); toast(notify.has(k) ? 'We’ll email you when ' + cfg(V) + ' is back' : 'Back-in-stock alert removed');
    return;
  }
  const item = Object.assign({}, V);
  bag.push(item);
  past.push({ bag: () => { bag.splice(bag.lastIndexOf(item), 1); renderBag(); addedEl.hidden = true; toast('Removed from bag'); } });
  fly(() => {
    renderBag();
    if (!RM.matches) bagBtn.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.18)' }, { transform: 'scale(1)' }], { duration: 500, easing: SPRING });
    addedEl.innerHTML = front(item, { still: 1 }) + '<small>Added to bag</small><b>Meridian Field ' + item.size + '</b><span>' + cfg(item).split(' / ').slice(0, 2).join(' / ') + ' · ' + usd(priceOf(item)) + '</span>';
    addedEl.hidden = false;
    clearTimeout(at); at = setTimeout(() => { addedEl.hidden = true; }, 3800);
  });
  const btn = $('.aps-pdp-add[data-act="add"]');
  btn.classList.add('is-done'); $('[data-addlabel]').textContent = 'Added ✓';
  setTimeout(() => { btn.classList.remove('is-done'); if (stock(V.case, V.dial, V.size)) $('[data-addlabel]').textContent = 'Add to bag · ' + usd(priceOf(V)); }, 1400);
  toast('Added ' + refOf(item) + ' to your bag', true);
}
/* a still of the watch arcs from the stage into the bag */
function fly(done) {
  const src = $('.aps-pdp-front > svg'), rr = root.getBoundingClientRect();
  if (RM.matches || !src || !stage.offsetParent) { done(); return; }
  const a = $('.aps-pdp-obj').getBoundingClientRect(), b = bagBtn.getBoundingClientRect();
  const c = doc.createElement('div');
  c.innerHTML = front(V, { still: 1 });
  Object.assign(c.style, { position: 'absolute', zIndex: 80, left: a.left - rr.left + 'px', top: a.top - rr.top + 'px', width: a.width + 'px', height: a.height + 'px', pointerEvents: 'none' });
  c.firstElementChild.style.cssText = 'width:100%;height:100%';
  root.append(c);
  const dx = b.left + b.width / 2 - (a.left + a.width / 2), dy = b.top + b.height / 2 - (a.top + a.height / 2), s = 28 / a.width;
  c.animate([
    { transform: 'none', opacity: 1 },
    { transform: 'translate(' + dx * .45 + 'px,' + (dy * .45 - 90) + 'px) scale(' + (s + .3) + ') rotate(-12deg)', opacity: 1, offset: .55 },
    { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + s + ') rotate(-24deg)', opacity: .2 }
  ], { duration: 820, easing: 'cubic-bezier(.5,0,.2,1)' }).onfinish = () => { c.remove(); done(); };
}

