root.addEventListener('change', e => {
  const t = e.target;
  if (t.type === 'radio') choose(t.closest('fieldset').dataset.g, t.value);
});
root.addEventListener('click', e => {
  const t = e.target;
  const th = t.closest('.aps-pdp-thumb'); if (th) { setZoom(false); return setView(+th.dataset.v); }
  const nv = t.closest('[data-step]'); if (nv) { setZoom(false); return setView(view + +nv.dataset.step); }
