  }
}
const SPRING = 'linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1)';
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const r2 = n => Math.round(n * 100) / 100;
const usd = n => (n < 0 ? '−' : '') + '$' + Math.abs(n).toFixed(2);
const FREE = 45, SHIP = 6.5, TAX = 0.0725, SUB_OFF = 0.10;

/* products: coffees carry a 250 g and a 1 kg price; gear has one price */
const P = {
  kib: { n: 'Kibira Washed', k: 'single', o: 'Burundi · Washed · Light', notes: 'Black tea, red currant, wildflower honey', p: { 250: 19, 1000: 64 }, lab: 'oklch(0.68 0.13 32)' },
  ham: { n: 'Hambela Natural', k: 'single', o: 'Ethiopia · Natural · Light', notes: 'Blueberry, cacao nib, jasmine', p: { 250: 21, 1000: 72 }, lab: 'oklch(0.62 0.11 355)' },
  pra: { n: 'La Pradera', k: 'single', o: 'Colombia · Honey · Medium', notes: 'Panela, orange zest, almond', p: { 250: 18, 1000: 60 }, lab: 'oklch(0.76 0.12 85)' },
  tol: { n: 'Decaf Tolima', k: 'single', o: 'Colombia · Sugarcane decaf', notes: 'Brown sugar, red apple, cocoa', p: { 250: 18, 1000: 60 }, lab: 'oklch(0.72 0.05 215)' },
  ngt: { n: 'Night Shift', k: 'blend', o: 'Brazil & Sumatra · Dark', notes: 'Molasses, cedar, dark chocolate', p: { 250: 16, 1000: 52 }, lab: 'oklch(0.42 0.03 265)' },
  fld: { n: 'Fieldhouse Espresso', k: 'blend', o: 'House blend · Medium-dark', notes: 'Hazelnut, toffee, stewed plum', p: { 250: 17, 1000: 56 }, lab: 'oklch(0.58 0.1 150)' },
  fil: { n: 'Paper filters, 100', k: 'gear', o: 'Unbleached, cone #2', p: { 1: 7 }, g: 'filter', lab: 'oklch(0.8 0.04 85)' },
  drp: { n: 'Stoneware dripper', k: 'gear', o: 'Single-cup, three holes', p: { 1: 32 }, g: 'dripper', lab: 'oklch(0.7 0.05 40)' },
  scp: { n: 'Brass bean scoop', k: 'gear', o: '10 g, solid brass', p: { 1: 14 }, g: 'scoop', lab: 'oklch(0.78 0.11 85)' },
  ket: { n: 'Gooseneck kettle', k: 'gear', o: '0.9 l, stovetop', p: { 1: 68 }, g: 'kettle', lab: 'oklch(0.55 0.02 250)' }
};
const GRINDS = [['whole', 'Whole bean'], ['filter', 'Filter'], ['espresso', 'Espresso'], ['press', 'French press']];
const CODES = {
  FIRSTPOUR: { label: '15% off coffee', calc: (lines) => r2(lines.filter(l => P[l.pid].k !== 'gear').reduce((s, l) => s + lineNet(l), 0) * 0.15) },
  KETTLE5: { label: '$5 off $40+', min: 40, calc: () => 5 }
};

let C = {
  lines: [
    { id: 'l1', pid: 'kib', size: 250, grind: 'whole', qty: 1, sub: 2 },
    { id: 'l2', pid: 'pra', size: 250, grind: 'filter', qty: 1, sub: 0 },
    { id: 'l3', pid: 'fil', size: 1, grind: null, qty: 1, sub: 0 }
  ],
  saved: [{ id: 'l4', pid: 'ham', size: 250, grind: 'whole', qty: 1, sub: 0 }],
  promo: null
};
let seq = 5, open = true, tab = 'all', done = null, focusLine = null;
const past = [];

const unit = l => P[l.pid].p[l.size];
const lineGross = l => r2(unit(l) * l.qty);
const lineSave = l => l.sub ? r2(lineGross(l) * SUB_OFF) : 0;
const lineNet = l => r2(lineGross(l) - lineSave(l));
function totals(c) {
  c = c || C;
  const merch = r2(c.lines.reduce((s, l) => s + lineGross(l), 0));
  const subs = r2(c.lines.reduce((s, l) => s + lineSave(l), 0));
  let promo = 0, promoNote = '';
  if (c.promo) {
    const code = CODES[c.promo];
    if (code.min && merch - subs < code.min) promoNote = 'Needs ' + usd(code.min) + ' of goods';
    else promo = Math.min(r2(code.calc(c.lines)), r2(merch - subs));
  }
  const net = r2(merch - subs - promo);
  const ship = !c.lines.length || net >= FREE ? 0 : SHIP;
  const tax = r2(net * TAX);
  const count = c.lines.reduce((s, l) => s + l.qty, 0);
  return { merch, subs, promo, promoNote, net, ship, tax, total: r2(net + ship + tax), count };
}

/* ── art: a kraft bag with a coloured label, or a piece of gear ── */
function art(pid) {
  const p = P[pid];
  if (p.g) {
    const g = {
      filter: '<path class="gf" d="M30 40h60l-14 60H44z"/><path class="gr" d="M30 40h60l-14 60H44zM36 54h48M40 70h40"/>',
      dripper: '<path class="gf" d="M28 44h64l-16 44H44z"/><path class="gr" d="M28 44h64l-16 44H44zM40 96h40M92 52q12 4 6 18l-8 4"/>',
      scoop: '<circle class="gf" cx="48" cy="72" r="20"/><path class="gr" d="M28 72a20 20 0 0 0 40 0M64 62l36-22"/>',
      kettle: '<path class="gf" d="M36 54h48l6 48H30z"/><path class="gr" d="M36 54h48l6 48H30zM50 54q10-14 20 0M30 70Q14 66 10 44M84 60q16 2 14 22"/>'
    }[p.g];
    return '<svg class="aps-cart-bag-svg" viewBox="0 0 120 130" style="--lab:' + p.lab + '" aria-hidden="true">' + g + '</svg>';
  }
  return '<svg class="aps-cart-bag-svg" viewBox="0 0 120 140" style="--lab:' + p.lab + '" aria-hidden="true">' +
    '<path class="kr" d="M24 26h72l4 102q0 6-6 6H26q-6 0-6-6z"/><path class="kd" d="M24 26h72l4 102q0 6-6 6h-8l-2-104z" opacity=".5"/>' +
    '<path class="kd" d="M22 12h76v16H22z"/><path d="M22 12l4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4 4-4 4 4" fill="none" stroke="rgb(0 0 0 / .25)" stroke-width="1.2"/>' +
    '<circle cx="60" cy="44" r="5" fill="rgb(0 0 0 / .28)"/><circle cx="60" cy="44" r="2" fill="rgb(255 255 255 / .25)"/>' +
    '<rect class="lb" x="32" y="60" width="56" height="54" rx="3"/><rect class="lt" x="40" y="70" width="40" height="5" rx="1.5"/><rect class="lt" x="40" y="80" width="28" height="3" rx="1.5" opacity=".7"/><circle cx="60" cy="98" r="7" fill="none" stroke="rgb(255 255 255 / .55)" stroke-width="1.6"/>' +
    '<path d="M20 30q2 50 2 98" stroke="rgb(255 255 255 / .12)" stroke-width="5" fill="none"/></svg>';
}

/* ── shop grid ── */
const gridEl = $('.aps-cart-grid');
function renderShop() {
  gridEl.innerHTML = Object.entries(P).filter(([, p]) => tab === 'all' || p.k === tab).map(([id, p]) =>
    '<li class="aps-cart-card" style="--lab:' + p.lab + '"><div class="aps-cart-art">' + art(id) + '</div><div><span class="aps-cart-tag">' + (p.k === 'single' ? 'Single origin' : p.k === 'blend' ? 'Blend' : 'Brew gear') + '</span><h3>' + p.n + '</h3><p>' + (p.notes || p.o) + '</p>' +
    '<div class="aps-cart-row"><b>' + (p.g ? usd(p.p[1]) : usd(p.p[250]) + ' <small>/ 250 g</small>') + '</b><button type="button" data-addp="' + id + '" aria-label="Add ' + p.n + ' to bag">Add</button></div></div></li>').join('');
}

/* ── odometer total: each digit is a strip that slides to its value ── */
function roll(el, text) {
  const chars = [...text];
  if (el.dataset.len !== String(chars.length) || el.dataset.shape !== text.replace(/\d/g, '0')) {
    el.innerHTML = chars.map((ch, i) => /\d/.test(ch) ? '<span class="aps-cart-roll" style="--i:' + (chars.length - i) + '"><span>' + '0123456789'.split('').map(d => '<span>' + d + '</span>').join('') + '</span></span>' : '<span>' + ch + '</span>').join('');
    el.dataset.len = chars.length; el.dataset.shape = text.replace(/\d/g, '0');
    void el.offsetWidth;
  }
  const kids = el.children;
  chars.forEach((ch, i) => { if (/\d/.test(ch)) kids[i].firstElementChild.style.setProperty('--d', ch); });
