      (coffee ? '<span class="aps-cart-sel"><select data-set="size" aria-label="Bag size" tabindex="-1"><option value="250"' + (l.size === 250 ? ' selected' : '') + '>250 g</option><option value="1000"' + (l.size === 1000 ? ' selected' : '') + '>1 kg</option></select></span>' +
