css:
.aps-checkout {
  --aps-checkout-bg: oklch(0.99 0.002 100);
  --aps-checkout-ink: oklch(0.22 0.01 95);
  --aps-checkout-accent: oklch(0.47 0.09 158);
  --aps-checkout-bad: oklch(0.55 0.19 27);
  --aps-checkout-surface: color-mix(in oklch, var(--aps-checkout-ink) 3.5%, var(--aps-checkout-bg));
  --aps-checkout-line: color-mix(in oklch, var(--aps-checkout-ink) 11%, transparent);
  --aps-checkout-line2: color-mix(in oklch, var(--aps-checkout-ink) 22%, transparent);
  --aps-checkout-mute: color-mix(in oklch, var(--aps-checkout-ink) 58%, var(--aps-checkout-bg));
  --aps-checkout-tint: color-mix(in oklch, var(--aps-checkout-accent) 9%, var(--aps-checkout-bg));
  --aps-checkout-ease: cubic-bezier(.2, .8, .2, 1);
  --aps-checkout-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-checkout-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --aps-checkout-dir: 28px;
  position: relative; width: 100%; height: var(--aps-checkout-h, 680px);
  container-type: inline-size; container-name: aps-checkout;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-checkout-bg); color: var(--aps-checkout-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--aps-checkout-accent);
  border: 1px solid var(--aps-checkout-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--aps-checkout-accent); outline-offset: 2px; border-radius: 8px; }
  & kbd { font: 600 10px/1 var(--aps-checkout-mono); padding: 3px 4px 2px; border-radius: 4px; background: rgb(255 255 255 / .16); color: inherit; opacity: .8; }

  /* ── header + stepper ── */
  & .aps-checkout-top { display: flex; align-items: center; gap: 24px; padding: 14px 24px; border-bottom: 1px solid var(--aps-checkout-line); }
  & .aps-checkout-brand { display: flex; align-items: baseline; gap: 7px;
    & b { font-size: 17px; font-weight: 850; letter-spacing: .26em; }
    & span { font-size: 12px; color: var(--aps-checkout-mute); }
  }
  & .aps-checkout-steps { list-style: none; margin: 0 auto; padding: 0; display: flex; align-items: center; gap: 4px; counter-reset: s;
    & li { display: flex; align-items: center; gap: 4px; }
    & li + li::before { content: ""; width: 26px; height: 2px; border-radius: 2px; background: linear-gradient(var(--aps-checkout-accent), var(--aps-checkout-accent)) no-repeat 0 0 / 0% 100%, var(--aps-checkout-line2); transition: background-size .5s var(--aps-checkout-ease); }
    & li.is-done + li::before { background-size: 100% 100%, auto; }
    & button { display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 10px 0 4px; border: 0; border-radius: 999px; background: none; font-size: 13px; font-weight: 550; color: var(--aps-checkout-mute); transition: background .2s, color .2s; }
    & button:disabled { cursor: default; }
    & button:not(:disabled):hover { background: var(--aps-checkout-surface); color: var(--aps-checkout-ink); }
    & i { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; border: 1.5px solid var(--aps-checkout-line2); transition: background .3s, border-color .3s, color .3s, scale .4s var(--aps-checkout-spring); }
    & li.is-on button { color: var(--aps-checkout-ink); }
    & li.is-on i { border-color: var(--aps-checkout-ink); background: var(--aps-checkout-ink); color: var(--aps-checkout-bg); }
    & li.is-done i { border-color: var(--aps-checkout-accent); background: var(--aps-checkout-accent); color: white; font-size: 0; }
    & li.is-done i::after { content: ""; width: 9px; height: 5px; border-left: 2px solid white; border-bottom: 2px solid white; rotate: -45deg; translate: 0 -1px; }
  }
  & .aps-checkout-secure { display: flex; align-items: center; gap: 6px; margin: 0; font-size: 12.5px; color: var(--aps-checkout-mute);
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; }
  }

  /* ── body ── */
  & .aps-checkout-body { position: relative; min-height: 0; display: grid; grid-template: "main sum" minmax(0, 1fr) / minmax(0, 1fr) minmax(320px, 37%); }
  & .aps-checkout-sumbar { display: none; }
  & .aps-checkout-main { grid-area: main; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; display: flex; flex-direction: column; padding: 8px clamp(18px, 4cqi, 52px) 0; }
  & .aps-checkout-step { flex: 1; padding-bottom: 20px;
    transition: opacity .3s, translate .5s var(--aps-checkout-spring);
    @starting-style { opacity: 0; translate: var(--aps-checkout-dir) 0; }
    & h2 { margin: 22px 0 12px; font-size: 18px; font-weight: 680; letter-spacing: -.015em; text-wrap: balance; }
