/* ── Oakhem · checkout. Four validated steps feed one order summary; the confirmation reads the same state ── */
const doc = root.ownerDocument;
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
/* scroll an element into view inside the component only, never the host page */
function reveal(n, center) {
  for (let p = n.parentElement; p && p !== root; p = p.parentElement) {
    const cs = getComputedStyle(p);
    if (!/auto|scroll/.test(cs.overflowY) || p.scrollHeight <= p.clientHeight) continue;
    const pr = p.getBoundingClientRect(), r = n.getBoundingClientRect();
    const d = center ? r.top + r.height / 2 - (pr.top + pr.height / 2) : r.top < pr.top + 12 ? r.top - pr.top - 12 : r.bottom > pr.bottom - 12 ? r.bottom - pr.bottom + 12 : 0;
