.aps-search {
  --aps-search-bg: oklch(0.165 0.004 260);
  --aps-search-fg: oklch(0.95 0.004 260);
  --aps-search-accent: oklch(0.89 0.17 100);
  --aps-search-good: oklch(0.8 0.13 155);
  --aps-search-panel: color-mix(in oklch, var(--aps-search-bg), white 4%);
  --aps-search-raise: color-mix(in oklch, var(--aps-search-bg), white 8.5%);
  --aps-search-line: color-mix(in oklch, var(--aps-search-fg) 10%, transparent);
  --aps-search-line2: color-mix(in oklch, var(--aps-search-fg) 20%, transparent);
  --aps-search-mute: color-mix(in oklch, var(--aps-search-fg) 55%, var(--aps-search-bg));
  --aps-search-hl: color-mix(in oklch, var(--aps-search-accent) 24%, transparent);
  --aps-search-ease: cubic-bezier(.2, .8, .2, 1);
  --aps-search-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-search-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--aps-search-h, 680px);
  container-type: inline-size; container-name: aps-search;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-search-bg); color: var(--aps-search-fg);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--aps-search-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--aps-search-accent); outline-offset: 2px; border-radius: 8px; }
  & kbd { font: 600 10px/1 var(--aps-search-mono); padding: 3px 5px 2px; border-radius: 4px; background: color-mix(in oklch, var(--aps-search-fg) 9%, transparent); color: var(--aps-search-mute); box-shadow: inset 0 -1px 0 rgb(0 0 0 / .5); }
  & mark { background: var(--aps-search-hl); color: var(--aps-search-accent); border-radius: 3px; padding: 0 1px; }
  & mark.is-fuzzy { background: none; color: var(--aps-search-accent); text-decoration: underline wavy color-mix(in oklch, var(--aps-search-accent) 60%, transparent); text-underline-offset: 3px; }
  & .aps-search-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* ── top bar with the combobox ── */
  & .aps-search-top { position: relative; z-index: 10; display: flex; align-items: center; gap: 20px; padding: 14px 22px; border-bottom: 1px solid var(--aps-search-line); }
  & .aps-search-brand { display: flex; align-items: center; gap: 8px; flex: none;
    & svg { width: 22px; height: 22px; fill: none; stroke: var(--aps-search-accent); stroke-width: 1.8; stroke-linecap: round; }
    & b { font-size: 17px; font-weight: 800; letter-spacing: -.02em; }
    & span { font-size: 11px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--aps-search-mute); }
  }
  & .aps-search-box { position: relative; flex: 1; max-width: 640px; display: flex; align-items: center;
    & input { width: 100%; height: 46px; padding: 0 92px 0 44px; border-radius: 12px; border: 1px solid var(--aps-search-line2); background: var(--aps-search-panel); font-size: 16.5px; outline: none; transition: border-color .2s, background .2s, box-shadow .3s var(--aps-search-ease); }
    & input::placeholder { color: var(--aps-search-mute); }
    & input:focus { border-color: var(--aps-search-accent); background: var(--aps-search-raise); box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-search-accent) 14%, transparent); }
    &:has(.aps-search-pop:not([hidden])) input { border-radius: 12px 12px 0 0; }
  }
  & .aps-search-glass { position: absolute; left: 14px; width: 19px; height: 19px; fill: none; stroke: var(--aps-search-mute); stroke-width: 2; stroke-linecap: round; pointer-events: none; }
  & .aps-search-ghost { position: absolute; left: 45px; right: 92px; font-size: 16.5px; white-space: pre; overflow: hidden; pointer-events: none; color: transparent;
    & i { font-style: normal; color: color-mix(in oklch, var(--aps-search-fg) 34%, transparent); }
  }
  & .aps-search-clear { position: absolute; right: 52px; width: 28px; height: 28px; border: 0; border-radius: 50%; background: none; display: grid; place-items: center; color: var(--aps-search-mute); opacity: 0; pointer-events: none; transition: opacity .2s, background .2s;
    & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
    &:hover { background: var(--aps-search-raise); color: var(--aps-search-fg); }
  }
  & .aps-search-box:has(input:not(:placeholder-shown)) .aps-search-clear { opacity: 1; pointer-events: auto; }
  & .aps-search-k { position: absolute; right: 12px; display: flex; gap: 1px; }
  & .aps-search-bag { position: relative; flex: none; margin-left: auto; width: 42px; height: 42px; border-radius: 50%; border: 1px solid var(--aps-search-line2); background: none; display: grid; place-items: center;
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; }
    & span { position: absolute; top: -3px; right: -4px; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 10px; display: grid; place-items: center; background: var(--aps-search-accent); color: var(--aps-search-bg); font: 700 11px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; transition: scale .35s var(--aps-search-spring); }
    & span:empty { scale: 0; }
  }

  /* suggestion panel */
  & .aps-search-pop { position: absolute; z-index: 30; left: 0; right: 0; top: 100%; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); border: 1px solid var(--aps-search-accent); border-top: 1px solid var(--aps-search-line); border-radius: 0 0 14px 14px; background: var(--aps-search-raise); box-shadow: 0 34px 60px -20px rgb(0 0 0 / .8); overflow: hidden;
    transform-origin: top; transition: opacity .18s, scale .3s var(--aps-search-spring), translate .3s var(--aps-search-spring);
    @starting-style { opacity: 0; scale: 1 .96; translate: 0 -4px; }
    & section { padding: 10px; min-width: 0; }
    & section + section { border-left: 1px solid var(--aps-search-line); }
    & h3 { display: flex; justify-content: space-between; margin: 4px 8px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--aps-search-mute); }
    & h3 button { border: 0; background: none; padding: 0; font: inherit; letter-spacing: .06em; color: var(--aps-search-mute); text-decoration: underline; text-underline-offset: 2px; }
    & ul { list-style: none; margin: 0 0 6px; padding: 0; }
    & footer { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 4px 14px; align-items: center; padding: 9px 14px; border-top: 1px solid var(--aps-search-line); font-size: 11.5px; color: var(--aps-search-mute); }
    & footer span { display: inline-flex; gap: 3px; align-items: center; }
    & footer b { margin-left: auto; color: var(--aps-search-fg); font-weight: 600; }
  }
  & .aps-search-opt { display: flex; align-items: center; gap: 10px; min-height: 36px; padding: 6px 8px; border-radius: 9px; cursor: pointer; font-size: 14px;
    & > svg { flex: none; width: 16px; height: 16px; fill: none; stroke: var(--aps-search-mute); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    & .q { min-width: 0; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--aps-search-mute); }
    & .q b { color: var(--aps-search-fg); font-weight: 650; }
    & small { margin-left: auto; font-size: 12px; color: var(--aps-search-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
    & .x { flex: none; width: 22px; height: 22px; border: 0; border-radius: 50%; background: none; display: grid; place-items: center; color: var(--aps-search-mute); opacity: 0; }
    & .x svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; }
    &:hover .x, &[aria-selected="true"] .x { opacity: 1; }
    & .x:hover { background: var(--aps-search-line2); color: var(--aps-search-fg); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--aps-search-accent) 12%, transparent); }
    &[aria-selected="true"] > svg { stroke: var(--aps-search-accent); }
  }
  & .aps-search-popp { gap: 12px; min-height: 54px;
    & .aps-search-ic { width: 40px; height: 40px; }
    & div { min-width: 0; flex: 1; }
    & div b { display: block; font-weight: 600; font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & div span { font-size: 12px; color: var(--aps-search-mute); }
    & small { color: var(--aps-search-fg); font-weight: 600; }
  }
  & .aps-search-chips { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 8px 8px;
    & .aps-search-opt { min-height: 30px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-search-line2); font-size: 13px; }
  }
  & .aps-search-ic { flex: none; display: grid; place-items: center; border-radius: 10px; background: color-mix(in oklch, var(--c) 18%, var(--aps-search-panel));
    & svg { width: 58%; height: 58%; fill: none; stroke: color-mix(in oklch, var(--c), white 30%); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  }

  /* ── results ── */
  & .aps-search-body { min-height: 0; display: grid; grid-template: "res peek" minmax(0, 1fr) / minmax(0, 1fr) minmax(300px, 36%); }
  & .aps-search-results { grid-area: res; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
  & .aps-search-head { position: sticky; top: 0; z-index: 3; padding: 18px 22px 12px; background: color-mix(in oklch, var(--aps-search-bg) 92%, transparent); backdrop-filter: blur(10px);
    & h1 { margin: 0; font-size: clamp(19px, 2.3cqi, 26px); font-weight: 650; letter-spacing: -.02em; text-wrap: balance; font-variant-numeric: tabular-nums; }
    & h1 q { color: var(--aps-search-accent); quotes: "\201C" "\201D"; }
    & h1 span { color: var(--aps-search-mute); font-weight: 450; }
  }
  @supports (animation-timeline: scroll()) {
    & .aps-search-head { animation: aps-search-stick linear both; animation-timeline: scroll(nearest block); animation-range: 0 60px; }
  }
  & .aps-search-fix { margin: 4px 0 0; font-size: 13.5px; color: var(--aps-search-mute); text-wrap: pretty;
    &:empty { display: none; }
    & b { color: var(--aps-search-fg); font-weight: 600; font-style: italic; }
    & button { border: 0; background: none; padding: 0; color: var(--aps-search-accent); text-decoration: underline; text-underline-offset: 3px; font-style: italic; }
  }
  & .aps-search-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; margin-top: 12px; }
  & .aps-search-cats { display: flex; gap: 6px; flex: 1 1 auto; min-width: 0; overflow-x: auto; scrollbar-width: none; }
  & .aps-search-cat, & .aps-search-tog { flex: none; height: 30px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-search-line2); background: none; font-size: 12.5px; font-weight: 550; transition: background .2s, color .2s, border-color .2s;
    & em { font-style: normal; margin-left: 5px; color: var(--aps-search-mute); font-variant-numeric: tabular-nums; }
    &:hover { border-color: var(--aps-search-fg); }
    &[aria-pressed="true"] { background: var(--aps-search-accent); border-color: var(--aps-search-accent); color: var(--aps-search-bg); }
    &[aria-pressed="true"] em { color: color-mix(in oklch, var(--aps-search-bg) 70%, transparent); }
  }
  & .aps-search-tools { display: flex; gap: 6px; align-items: center; }
  & .aps-search-sort select { height: 30px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--aps-search-line2); background: var(--aps-search-panel); font-size: 12.5px; cursor: pointer; }

  & .aps-search-list { list-style: none; margin: 0; padding: 4px 12px 8px; }
  & .aps-search-row { position: relative; display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; gap: 2px 14px; align-items: center; padding: 12px 10px; border-radius: 12px; cursor: pointer; transition: background .2s;
    animation: aps-search-rise .45s var(--aps-search-spring) calc(var(--i, 0) * 28ms) both;
    & .aps-search-ic { grid-row: span 3; width: 52px; height: 52px; }
    & h3 { margin: 0; font-size: 15px; font-weight: 620; letter-spacing: -.01em; }
    & .aps-search-by { font-size: 12.5px; color: var(--aps-search-mute); }
    & .aps-search-spec { grid-column: 2; margin: 3px 0 0; font: 12px/1.4 var(--aps-search-mono); color: color-mix(in oklch, var(--aps-search-fg) 72%, transparent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .aps-search-pr { grid-column: 3; grid-row: 1 / span 2; text-align: right; }
    & .aps-search-pr b { display: block; font-size: 15px; font-weight: 650; font-variant-numeric: tabular-nums; }
    & .aps-search-pr span { font-size: 12px; color: var(--aps-search-mute); }
    & .aps-search-pr .is-back { color: oklch(0.78 0.12 60); }
    &:hover { background: var(--aps-search-panel); }
    &[aria-selected="true"] { background: var(--aps-search-raise); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 14px; bottom: 14px; width: 3px; border-radius: 0 3px 3px 0; background: var(--aps-search-accent); }
  }
  & .aps-search-none { padding: 40px 22px; text-align: center; color: var(--aps-search-mute);
    & h3 { margin: 0 0 6px; color: var(--aps-search-fg); font-size: 18px; text-wrap: balance; }
    & p { margin: 0 auto 14px; max-width: 42ch; text-wrap: pretty; }
    & div { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
    & button { height: 32px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-search-line2); background: none; font-size: 13px; }
  }
  & .aps-search-keys { display: flex; flex-wrap: wrap; gap: 6px 16px; margin: 0; padding: 12px 22px 18px; border-top: 1px solid var(--aps-search-line); font-size: 12px; color: var(--aps-search-mute);
    & span { display: inline-flex; gap: 3px; align-items: center; }
  }

  /* ── preview ── */
  & .aps-search-peek { grid-area: peek; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; border-left: 1px solid var(--aps-search-line); background: var(--aps-search-panel); }
  & .aps-search-pv { padding: 18px 22px 24px; animation: aps-search-fade .35s var(--aps-search-ease) both;
    & .aps-search-back { display: none; align-items: center; gap: 6px; height: 34px; margin: -4px 0 8px -6px; padding: 0 10px 0 6px; border: 0; border-radius: 9px; background: none; font-weight: 600; color: var(--aps-search-mute); }
    & .aps-search-back svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
    & .aps-search-hero { position: relative; aspect-ratio: 16 / 10; border-radius: 16px; display: grid; place-items: center; overflow: hidden; background: radial-gradient(70% 80% at 50% 40%, color-mix(in oklch, var(--c) 30%, var(--aps-search-raise)), var(--aps-search-bg)); }
    & .aps-search-hero svg { width: 46%; height: 70%; fill: color-mix(in oklch, var(--c) 22%, transparent); stroke: color-mix(in oklch, var(--c), white 45%); stroke-width: .9; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 18px 24px rgb(0 0 0 / .5)); animation: aps-search-float .7s var(--aps-search-spring) both; }
    & .aps-search-hero span { position: absolute; left: 12px; top: 12px; padding: 3px 9px; border-radius: 999px; background: rgb(0 0 0 / .35); font-size: 11px; font-weight: 600; letter-spacing: .06em; }
    & h2 { margin: 16px 0 2px; font-size: 21px; line-height: 1.15; font-weight: 680; letter-spacing: -.02em; text-wrap: balance; }
    & .aps-search-by { margin: 0; color: var(--aps-search-mute); font-size: 13px; }
    & .aps-search-buy { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 14px 0; }
    & .aps-search-buy b { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
    & .aps-search-buy button { height: 42px; padding: 0 16px; border-radius: 11px; border: 0; background: var(--aps-search-accent); color: var(--aps-search-bg); font-weight: 700; display: flex; align-items: center; gap: 8px; transition: scale .25s var(--aps-search-spring); }
    & .aps-search-buy button:active { scale: .96; }
    & .aps-search-buy kbd { background: rgb(0 0 0 / .12); color: inherit; box-shadow: none; }
    & .aps-search-stock { margin: 0 0 14px; font-size: 13px; color: var(--aps-search-good); }
    & .aps-search-stock.is-back { color: oklch(0.78 0.12 60); }
    & h4 { margin: 16px 0 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--aps-search-mute); }
    & dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; margin: 0; font-size: 13px; }
    & dt { color: var(--aps-search-mute); }
    & dd { margin: 0; font-family: var(--aps-search-mono); font-size: 12.5px; }
    & .aps-search-why { display: flex; flex-wrap: wrap; gap: 6px; }
    & .aps-search-why span { padding: 3px 9px; border-radius: 999px; background: var(--aps-search-raise); font-size: 12px; color: var(--aps-search-mute); }
    & .aps-search-why b { color: var(--aps-search-accent); font-weight: 600; }
    & .aps-search-sim { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
    & .aps-search-sim button { width: 100%; display: flex; align-items: center; gap: 10px; padding: 6px; border: 0; border-radius: 10px; background: none; text-align: left; font-size: 13px; }
    & .aps-search-sim button:hover { background: var(--aps-search-raise); }
    & .aps-search-sim .aps-search-ic { width: 34px; height: 34px; border-radius: 8px; }
    & .aps-search-sim span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .aps-search-sim small { font-variant-numeric: tabular-nums; color: var(--aps-search-mute); }
  }
  & .aps-search-stars { color: var(--aps-search-accent); letter-spacing: 1px; }

  & .aps-search-toast { position: absolute; z-index: 60; left: 50%; bottom: 18px; display: flex; align-items: center; gap: 14px; max-width: calc(100% - 32px); padding: 10px 10px 10px 16px; border-radius: 12px; background: var(--aps-search-fg); color: var(--aps-search-bg); font-size: 13px; font-weight: 500; box-shadow: 0 18px 40px -12px rgb(0 0 0 / .6);
    translate: -50% 160%; opacity: 0; pointer-events: none; transition: translate .5s var(--aps-search-spring), opacity .2s;
    & [data-msg] { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    & button { flex: none; height: 28px; padding: 0 10px; border-radius: 7px; border: 0; background: color-mix(in oklch, var(--aps-search-bg) 12%, transparent); font-weight: 650; font-size: 12.5px; color: inherit; }
    &:not(.has-undo) button { display: none; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }

  @container aps-search (max-width: 959px) {
    & .aps-search-brand span { display: none; }
    & .aps-search-body { grid-template-columns: minmax(0, 1fr) minmax(280px, 40%); }
    & .aps-search-pop { grid-template-columns: 1fr; }
    & .aps-search-pop section + section { border-left: 0; border-top: 1px solid var(--aps-search-line); }
  }
  @container aps-search (max-width: 759px) {
    & .aps-search-top { gap: 12px; padding: 12px 14px; }
    & .aps-search-brand b { display: none; }
    & .aps-search-k { display: none; }
    & .aps-search-box input { padding-right: 44px; font-size: 16px; }
    & .aps-search-clear { right: 8px; }
    & .aps-search-body { grid-template: "res" minmax(0, 1fr) / minmax(0, 1fr); }
    & .aps-search-peek { grid-area: res; border-left: 0; z-index: 5; background: var(--aps-search-bg); translate: 102% 0; visibility: hidden; transition: translate .5s var(--aps-search-spring), visibility 0s .5s; }
    &[data-view="detail"] .aps-search-peek { translate: 0 0; visibility: visible; transition: translate .5s var(--aps-search-spring), visibility 0s; }
    & .aps-search-pv .aps-search-back { display: inline-flex; }
    & .aps-search-head { padding: 14px 14px 10px; }
    & .aps-search-list { padding: 4px 6px 8px; }
    & .aps-search-keys { display: none; }
    & .aps-search-pop { left: -2px; right: -2px; }
  }
  @container aps-search (max-width: 440px) {
    & .aps-search-row { grid-template-columns: 44px minmax(0, 1fr) auto; gap: 2px 10px; padding: 10px 8px; }
    & .aps-search-row .aps-search-ic { width: 44px; height: 44px; }
    & .aps-search-row .aps-search-spec { grid-column: 1 / -1; }
    & .aps-search-tools { flex-wrap: wrap; }
  }

  @media (prefers-reduced-motion: reduce) {
    & .aps-search-row, & .aps-search-pv, & .aps-search-pv .aps-search-hero svg { animation: none; }
    & .aps-search-pop { transition: opacity .15s; }
    & .aps-search-peek, &[data-view="detail"] .aps-search-peek { transition: visibility 0s; }
    & .aps-search-head { animation: none; border-bottom: 1px solid var(--aps-search-line); }
  }
}

@keyframes aps-search-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes aps-search-fade { from { opacity: 0; } }
@keyframes aps-search-float { from { opacity: 0; translate: 0 14px; scale: .94; } }
@keyframes aps-search-stick { to { box-shadow: 0 1px 0 var(--aps-search-line), 0 14px 24px -18px rgb(0 0 0 / .9); } }

