    '<button type="button" class="aps-search-back" data-act="back"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>Results</button>' +
    '<div class="aps-search-hero"><span>' + CATS[p.cat][0] + '</span><svg viewBox="0 0 24 24" aria-hidden="true">' + CATS[p.cat][2] + '</svg></div>' +
    '<h2>' + esc(p.name) + '</h2><p class="aps-search-by">' + esc(p.brand) + ' · <span class="aps-search-stars">' + '★'.repeat(Math.round(p.rating)) + '</span> ' + p.rating.toFixed(1) + '</p>' +
    '<div class="aps-search-buy"><b>' + usd(p.price) + '</b><button type="button" data-add="' + p.id + '">Add to bag <kbd>B</kbd></button></div>' +
    '<p class="aps-search-stock' + (p.stock ? '' : ' is-back') + '">' + (p.stock ? p.stock + ' in the warehouse · ships tomorrow' : 'On backorder · ships in about two weeks') + '</p>' +
    '<h4>Why this matched</h4><div class="aps-search-why">' + r.why.map(w => '<span><b>' + esc(w[0]) + '</b> ' + (w[3] ? '≈ ' + esc(w[2]) + ' ' : '') + 'in ' + FN[w[1]] + '</span>').join('') + '</div>' +
    '<h4>Specs</h4><dl>' + p.specs.map((s, i) => '<dt>' + ['Type', 'Design', 'Detail', 'Extra', 'Also'][i] + '</dt><dd>' + esc(s) + '</dd>').join('') + '</dl>' +
    '<h4>More ' + CATS[p.cat][0].toLowerCase() + '</h4><ul class="aps-search-sim">' + sim.map(s => '<li><button type="button" data-jump="' + s.id + '">' + ic(s.cat) + '<span>' + esc(s.name) + '</span><small>' + usd(s.price) + '</small></button></li>').join('') + '</ul></div>';
}
function openDetail(on) { root.dataset.view = on ? 'detail' : 'list'; if (on && root.clientWidth < 760) { const b = $('.aps-search-back'); if (b) b.focus({ preventScroll: true }); } }

/* ── bag + toast ── */
let tt = 0;
const toastEl = $('.aps-search-toast');
function toast(msg, undoable) {
  $('[data-msg]', toastEl).textContent = msg;
  toastEl.classList.toggle('has-undo', !!undoable);
  toastEl.classList.remove('is-on'); void toastEl.offsetWidth; toastEl.classList.add('is-on');
  clearTimeout(tt); tt = setTimeout(() => toastEl.classList.remove('is-on'), 3600);
}
function renderBag() { $('[data-bag]').textContent = bag.length || ''; $('.aps-search-bag').setAttribute('aria-label', 'Bag, ' + bag.length + ' item' + (bag.length === 1 ? '' : 's') + (bag.length ? ', ' + usd(bag.reduce((s, id) => s + byId[id].price, 0)) : '')); }
function add(id) {
  bag.push(id); renderBag();
  if (!RM.matches) $('.aps-search-bag').animate([{ transform: 'scale(1)' }, { transform: 'scale(1.18)' }, { transform: 'scale(1)' }], { duration: 450, easing: 'cubic-bezier(.3,1.6,.5,1)' });
  toast('Added ' + byId[id].name + ' · ' + usd(byId[id].price), true);
}
toastEl.addEventListener('click', e => { if (e.target.closest('[data-undo]') && bag.length) { const id = bag.pop(); renderBag(); toast('Removed ' + byId[id].name); } });
$('.aps-search-bag').addEventListener('click', () => toast(bag.length ? bag.length + ' in your bag · ' + usd(bag.reduce((s, id) => s + byId[id].price, 0)) : 'Your bag is empty. Press B on a result to add it.'));

/* ── events ── */
input.addEventListener('focus', () => openPop(true));
input.addEventListener('input', () => { openPop(true); });
input.addEventListener('keydown', e => {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    if (pop.hidden) { openPop(true); return; }
    const N = opts.length;
    if (!N) return;
    /* -1 is the text field itself, so the list wraps through it */
    act = e.key === 'ArrowDown' ? (act + 1 >= N ? -1 : act + 1) : (act - 1 < -1 ? N - 1 : act - 1);
    syncAct();
  } else if (e.key === 'Enter') {
    e.preventDefault(); choose(act >= 0 ? opts[act] : null);
  } else if (e.key === 'Tab' && !pop.hidden && !e.shiftKey) {
    const o = act >= 0 ? opts[act] : opts.find(x => x.type === 'q' && x.q.toLowerCase().startsWith(input.value.toLowerCase()) && x.q.length > input.value.length);
    if (o && o.q && o.type === 'q' && input.value.trim()) { e.preventDefault(); input.value = o.q + ' '; renderPop(); }
