input.addEventListener('blur', () => setTimeout(() => {
  if ($('.aps-search-box').contains(doc.activeElement) || pop.hidden) return;
  openPop(false);
  if (!input.value.trim()) input.value = Q;
}, 120));
pop.addEventListener('pointerdown', e => e.preventDefault());
pop.addEventListener('click', e => {
  const f = e.target.closest('[data-forget]');
  if (f) { recent = recent.filter(q => q !== f.dataset.forget); renderPop(); return; }
  if (e.target.closest('[data-act="clear-recent"]')) { recent = []; renderPop(); return; }
  const o = e.target.closest('[data-o]'); if (o) choose(opts[+o.dataset.o]);
});
pop.addEventListener('pointermove', e => { const o = e.target.closest('[data-o]'); if (o && +o.dataset.o !== act) { act = +o.dataset.o; syncAct(); } });

root.addEventListener('click', e => {
  const t = e.target;
  if (t.closest('.aps-search-pop')) return;
  if (t.closest('.aps-search-clear')) { input.value = ''; input.focus({ preventScroll: true }); openPop(true); return; }
  const row = t.closest('.aps-search-row'); if (row) { sel = row.dataset.id; syncSel(); renderPeek(); openDetail(true); return; }
  const c = t.closest('[data-cat]'); if (c) { cat = c.dataset.cat || null; renderResults(); return; }
