  const a = t.closest('[data-add]'); if (a) { add(a.dataset.add); return; }
  const j = t.closest('[data-jump]'); if (j) { const id = j.dataset.jump; if (!R.some(r => r.p.id === id)) run(byId[id].name); sel = id; syncSel(true); renderPeek(); return; }
  const ac = t.closest('[data-act]'); if (!ac) return;
  if (ac.dataset.act === 'back') { openDetail(false); const n = listEl.querySelector('[data-id="' + sel + '"]'); if (n) listEl.focus({ preventScroll: true }); }
  else if (ac.dataset.act === 'reset-f') { cat = null; under = false; inStock = false; $$('[data-f]').forEach(b => b.setAttribute('aria-pressed', 'false')); renderResults(); }
});
$('.aps-search-sort select').addEventListener('change', e => { sort = e.target.value; renderResults(); });
listEl.tabIndex = 0;

root.addEventListener('keydown', e => {
  const t = e.target;
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); input.focus({ preventScroll: true }); input.select(); return; }
  if (t === input || t.matches('select') || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === '/') { e.preventDefault(); input.focus({ preventScroll: true }); input.select(); return; }
  if (e.key === 'Escape' && root.dataset.view === 'detail') { openDetail(false); listEl.focus({ preventScroll: true }); return; }
  if (!R || !R.length) return;
  const i = R.findIndex(r => r.p.id === sel);
  const k = e.key.toLowerCase();
  if (k === 'j' || k === 'k' || ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && t === listEl)) {
    e.preventDefault();
    const n = R[Math.max(0, Math.min(R.length - 1, i + (k === 'j' || e.key === 'ArrowDown' ? 1 : -1)))];
    sel = n.p.id; syncSel(true); renderPeek();
  } else if (e.key === 'Enter' && t === listEl) { openDetail(true); }
  else if (k === 'b' && sel) add(sel);
});

/* first paint: a search already run, a typo hint in the placeholder */
input.value = Q;
renderResults();
renderBag();
input.placeholder = 'Try “studio monitr” or “wireles headphnes”';

css:
@property --aps-orders-f { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.aps-orders {
  --aps-orders-bg: oklch(0.975 0.004 240);
  --aps-orders-ink: oklch(0.24 0.02 250);
  --aps-orders-accent: oklch(0.66 0.18 45);
  --aps-orders-good: oklch(0.56 0.12 155);
  --aps-orders-land: oklch(0.945 0.018 135);
  --aps-orders-water: oklch(0.88 0.035 230);
  --aps-orders-card: color-mix(in oklch, var(--aps-orders-bg), white 70%);
  --aps-orders-line: color-mix(in oklch, var(--aps-orders-ink) 10%, transparent);
  --aps-orders-line2: color-mix(in oklch, var(--aps-orders-ink) 20%, transparent);
  --aps-orders-mute: color-mix(in oklch, var(--aps-orders-ink) 56%, var(--aps-orders-bg));
  --aps-orders-tint: color-mix(in oklab, var(--aps-orders-accent) 10%, var(--aps-orders-card));
  --aps-orders-ease: cubic-bezier(.2, .8, .2, 1);
  --aps-orders-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-orders-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--aps-orders-h, 680px);
  container-type: inline-size; container-name: aps-orders;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-orders-bg); color: var(--aps-orders-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--aps-orders-accent);
  border: 1px solid var(--aps-orders-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--aps-orders-accent); outline-offset: 2px; border-radius: 8px; }
  & kbd { font: 600 10px/1 var(--aps-orders-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--aps-orders-line2); border-bottom-width: 2px; background: var(--aps-orders-card); color: var(--aps-orders-mute); }

  & .aps-orders-top { display: flex; align-items: center; gap: 18px; padding: 12px 20px; background: var(--aps-orders-card); border-bottom: 1px solid var(--aps-orders-line); }
  & .aps-orders-brand { display: flex; align-items: center; gap: 8px;
    & svg { width: 24px; height: 24px; fill: var(--aps-orders-ink); }
    & b { font-size: 15px; font-weight: 800; letter-spacing: .2em; text-transform: uppercase; }
    & span { font-size: 12px; color: var(--aps-orders-mute); }
  }
  & .aps-orders-crumb { margin: 0 auto 0 8px; font-size: 13px; color: var(--aps-orders-mute);
    & span { margin: 0 6px; opacity: .5; } & b { color: var(--aps-orders-ink); font-weight: 600; }
  }
  & .aps-orders-me { display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 550;
    & i { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 12px; font-weight: 700; background: var(--aps-orders-ink); color: var(--aps-orders-card); }
  }

  & .aps-orders-body { min-height: 0; display: grid; grid-template: "nav list detail" minmax(0, 1fr) / 196px minmax(280px, 330px) minmax(0, 1fr); }

  /* ── filters ── */
  & .aps-orders-nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 16px 12px; border-right: 1px solid var(--aps-orders-line); }
  & .aps-orders-find { position: relative; display: flex; align-items: center;
    & svg { position: absolute; left: 10px; width: 15px; height: 15px; fill: none; stroke: var(--aps-orders-mute); stroke-width: 2; stroke-linecap: round; pointer-events: none; }
    & input { width: 100%; height: 36px; padding: 0 30px 0 32px; border-radius: 10px; border: 1px solid var(--aps-orders-line2); background: var(--aps-orders-card); font-size: 13px; outline: none; transition: border-color .2s, box-shadow .2s; }
    & input::-webkit-search-cancel-button { display: none; }
    & input:focus { border-color: var(--aps-orders-ink); box-shadow: 0 0 0 3px color-mix(in oklch, var(--aps-orders-ink) 8%, transparent); }
    & kbd { position: absolute; right: 8px; }
    &:focus-within kbd { opacity: 0; }
  }
  & .aps-orders-filters { display: grid; gap: 2px;
    & button { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border: 0; border-radius: 9px; background: none; font-size: 13.5px; font-weight: 550; color: var(--aps-orders-mute); text-align: left; transition: background .2s, color .2s; }
    & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
    & button span { flex: 1; }
    & button em { font-style: normal; font-size: 12px; font-variant-numeric: tabular-nums; }
    & button:hover { background: color-mix(in oklch, var(--aps-orders-ink) 5%, transparent); color: var(--aps-orders-ink); }
    & [aria-selected="true"] { background: var(--aps-orders-card); color: var(--aps-orders-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--aps-orders-ink) 12%, transparent), inset 0 0 0 1px var(--aps-orders-line); }
  }
  & .aps-orders-keys { margin: auto 0 0; display: grid; gap: 6px; font-size: 11.5px; color: var(--aps-orders-mute);
    & span { display: flex; align-items: center; gap: 3px; }
  }

  /* ── order list ── */
  & .aps-orders-list { grid-area: list; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; border-right: 1px solid var(--aps-orders-line);
    & ol { list-style: none; margin: 0; padding: 10px; display: grid; gap: 8px; outline: none; }
  }
  & .aps-orders-row { position: relative; display: grid; grid-template-columns: 1fr auto; gap: 4px 10px; padding: 12px 14px; border-radius: 14px; background: var(--aps-orders-card); border: 1px solid var(--aps-orders-line); cursor: pointer; transition: border-color .2s, box-shadow .25s, translate .35s var(--aps-orders-spring);
    animation: aps-orders-in .45s var(--aps-orders-spring) calc(var(--i, 0) * 35ms) both;
    & b { font: 600 13px var(--aps-orders-mono); letter-spacing: .02em; }
    & time { font-size: 12.5px; color: var(--aps-orders-mute); text-align: right; font-variant-numeric: tabular-nums; }
    & .aps-orders-thumbs { grid-column: 1 / -1; display: flex; gap: 6px; margin: 4px 0; }
    & .aps-orders-thumbs .aps-orders-g { width: 36px; height: 36px; border-radius: 9px; }
    & .aps-orders-thumbs small { align-self: center; font-size: 12px; color: var(--aps-orders-mute); }
    & .aps-orders-total { text-align: right; font-weight: 650; font-variant-numeric: tabular-nums; }
    &:hover { border-color: var(--aps-orders-line2); }
    &[aria-selected="true"] { border-color: var(--aps-orders-ink); box-shadow: 0 8px 20px -14px color-mix(in oklch, var(--aps-orders-ink) 60%, transparent); }
    &.is-live::after { content: ""; position: absolute; right: 12px; top: 12px; }
  }
  & .aps-orders-pill { justify-self: start; display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 999px; font-size: 11.5px; font-weight: 650; background: color-mix(in oklch, var(--c) 13%, transparent); color: color-mix(in oklab, var(--c), var(--aps-orders-ink) 30%);
    &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
    &.is-live::before { animation: aps-orders-pulse 1.6s ease-out infinite; }
  }
  & .aps-orders-g { flex: none; display: grid; place-items: center; background: color-mix(in oklab, var(--t) 22%, var(--aps-orders-card));
    & svg { width: 62%; height: 62%; fill: none; stroke: color-mix(in oklch, var(--t), black 35%); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  }
  & .aps-orders-empty { padding: 30px 16px; text-align: center; color: var(--aps-orders-mute); text-wrap: pretty; }

  /* ── detail ── */
  & .aps-orders-detail { grid-area: detail; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; position: relative; }
  & .aps-orders-d { padding: 18px clamp(16px, 2.6cqi, 30px) 28px; animation: aps-orders-fade .35s var(--aps-orders-ease) both; }
  & .aps-orders-back { display: none; align-items: center; gap: 4px; height: 32px; margin: -4px 0 8px -6px; padding: 0 10px 0 4px; border: 0; border-radius: 8px; background: none; font-weight: 600; color: var(--aps-orders-mute);
    & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  }
  & .aps-orders-dh { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 8px 16px;
    & > div:first-child { flex: 1 1 220px; }
    & h2 { margin: 0; font-size: clamp(20px, 2.4cqi, 26px); font-weight: 700; letter-spacing: -.02em; text-wrap: balance; }
    & h2 span { font-family: var(--aps-orders-mono); font-weight: 600; font-size: .8em; letter-spacing: 0; }
    & p { margin: 2px 0 0; color: var(--aps-orders-mute); font-size: 13px; }
  }
  & .aps-orders-acts { display: flex; flex-wrap: wrap; gap: 6px;
    & button { height: 36px; padding: 0 14px; border-radius: 10px; border: 1px solid var(--aps-orders-line2); background: var(--aps-orders-card); font-size: 13px; font-weight: 600; display: inline-flex; align-items: center; gap: 6px; transition: background .2s, border-color .2s; }
    & button:hover { border-color: var(--aps-orders-ink); }
    & button.is-main { background: var(--aps-orders-ink); border-color: var(--aps-orders-ink); color: var(--aps-orders-card); }
