  & .aps-orders-eta { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 6px 16px; padding: 16px 18px 12px;
    & small { display: block; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--aps-orders-mute); }
    & b { display: block; font-size: clamp(19px, 2.4cqi, 24px); font-weight: 700; letter-spacing: -.02em; text-wrap: balance; }
    & span { font-size: 12.5px; color: var(--aps-orders-mute); font-family: var(--aps-orders-mono); }
  }
  & .aps-orders-steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; padding: 0 18px 14px; list-style: none; margin: 0;
    & li { display: grid; gap: 6px; font-size: 12px; font-weight: 600; color: var(--aps-orders-mute); transition: --aps-orders-f .9s var(--aps-orders-ease); }
    & li::before { content: ""; height: 5px; border-radius: 3px; background: linear-gradient(90deg, var(--aps-orders-accent) var(--aps-orders-f), var(--aps-orders-line) 0); }
