  }
  & .aps-orders-map { position: relative; background: var(--aps-orders-land); border-top: 1px solid var(--aps-orders-line);
    & svg { width: 100%; height: auto; }
    & .wt { fill: var(--aps-orders-water); }
    & .pk { fill: color-mix(in oklab, var(--aps-orders-land), oklch(0.7 0.1 140) 22%); }
    & .rd { fill: none; stroke: white; stroke-width: 5; stroke-linecap: round; }
    & .rd2 { fill: none; stroke: white; stroke-width: 2.5; stroke-linecap: round; }
    & .rt { fill: none; stroke: color-mix(in oklch, var(--aps-orders-ink) 30%, transparent); stroke-width: 3; stroke-dasharray: 2 6; stroke-linecap: round; }
    & .rd-on { fill: none; stroke: var(--aps-orders-accent); stroke-width: 4; stroke-linecap: round; transition: stroke-dashoffset 1.4s var(--aps-orders-ease); }
    & .hub circle { fill: white; stroke: var(--aps-orders-ink); stroke-width: 2; }
    & .hub.is-past circle { fill: var(--aps-orders-accent); stroke: white; }
    & text { font: 600 10.5px system-ui, sans-serif; fill: color-mix(in oklch, var(--aps-orders-ink) 70%, transparent); paint-order: stroke; stroke: var(--aps-orders-land); stroke-width: 3px; }
    & .lbl-w { fill: color-mix(in oklab, var(--aps-orders-water), black 35%); font-style: italic; font-weight: 500; stroke: none; }
    & .van circle { fill: var(--aps-orders-accent); }
    & .van .halo { fill: var(--aps-orders-accent); opacity: .25; transform-box: fill-box; transform-origin: center; animation: aps-orders-halo 1.8s ease-out infinite; }
    & .van path { fill: none; stroke: white; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    & .home path { fill: var(--aps-orders-ink); }
  }
  & .aps-orders-events { list-style: none; margin: 0; padding: 14px 18px 6px; border-top: 1px solid var(--aps-orders-line);
    & li { position: relative; display: grid; grid-template-columns: 18px 1fr auto; gap: 10px; padding-bottom: 14px; font-size: 13px; }
    & li::before { content: ""; width: 10px; height: 10px; margin: 4px 0 0 4px; border-radius: 50%; background: var(--aps-orders-card); border: 2px solid var(--aps-orders-line2); z-index: 1; }
    & li:not(:last-child)::after { content: ""; position: absolute; left: 8px; top: 14px; bottom: 0; width: 2px; background: var(--aps-orders-line); }
    & li:first-child::before { border-color: var(--aps-orders-accent); background: var(--aps-orders-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--aps-orders-accent) 18%, transparent); }
