.aps-wishlist {
  --aps-wishlist-bg: oklch(0.195 0.014 205);
  --aps-wishlist-fg: oklch(0.95 0.01 200);
  --aps-wishlist-accent: oklch(0.71 0.165 32);
  --aps-wishlist-good: oklch(0.83 0.12 165);
  --aps-wishlist-panel: color-mix(in oklab, var(--aps-wishlist-bg), white 4.5%);
  --aps-wishlist-raise: color-mix(in oklab, var(--aps-wishlist-bg), white 9%);
