  }
  & .aps-wishlist-tog { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--aps-wishlist-line2); background: none; font-size: 12.5px; font-weight: 550; transition: background .2s, border-color .2s, color .2s;
