  if (t === itemsEl && e.key === ' ') { e.preventDefault(); if (S.cur) toggleSel(S.cur); return; }
  if (t === itemsEl && e.key === 'Enter') { root.dataset.view = 'detail'; if (handle) handle.focus({ preventScroll: true }); return; }
  if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && t !== handle && it(S.cur)) { e.preventDefault(); setTarget(it(S.cur).target + (e.key === 'ArrowRight' ? 5 : -5), true); return; }
  if (k === 'a' && it(S.cur)) { const box = $('[data-act="alert"]', detail); if (box) box.click(); return; }
  if ((e.key === 'Delete' || e.key === 'Backspace') && S.cur) { e.preventDefault(); removeIds(S.sel.length ? S.sel.slice() : [S.cur]); }
});

/* pause the draw-on when the component is off screen */
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);

renderLists();
renderItems(true);
renderDetail(true);
renderBag();

