@property --aps-bundle-fill { syntax: "<number>"; inherits: false; initial-value: 0; }

.aps-bundle {
  --aps-bundle-bg: oklch(0.965 0.014 60);
  --aps-bundle-ink: oklch(0.28 0.035 30);
  --aps-bundle-accent: oklch(0.56 0.16 18);
  --aps-bundle-kraft: oklch(0.75 0.065 68);
  --aps-bundle-rib: var(--aps-bundle-accent);
  --aps-bundle-card: color-mix(in oklab, var(--aps-bundle-bg), white 65%);
  --aps-bundle-tissue: color-mix(in oklab, var(--aps-bundle-bg), white 45%);
  --aps-bundle-line: color-mix(in oklab, var(--aps-bundle-ink) 11%, transparent);
  --aps-bundle-line2: color-mix(in oklab, var(--aps-bundle-ink) 22%, transparent);
  --aps-bundle-mute: color-mix(in oklab, var(--aps-bundle-ink) 58%, var(--aps-bundle-bg));
  --aps-bundle-tint: color-mix(in oklab, var(--aps-bundle-accent) 10%, var(--aps-bundle-card));
  --aps-bundle-ease: cubic-bezier(.2, .8, .2, 1);
  --aps-bundle-spring: linear(0, 0.009, 0.035 2.1%, 0.141, 0.281 6.7%, 0.723 12.9%, 0.938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%, 0.997 69.8%, 1.003 76.9%, 1);
  --aps-bundle-soft: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --aps-bundle-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --aps-bundle-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--aps-bundle-h, 680px);
  container-type: inline-size; container-name: aps-bundle;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  overflow: clip; isolation: isolate; box-sizing: border-box; border-radius: 14px;
  background: var(--aps-bundle-bg); color: var(--aps-bundle-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--aps-bundle-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--aps-bundle-accent); outline-offset: 2px; border-radius: 8px; }
  & kbd { font: 600 10px/1 var(--aps-bundle-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--aps-bundle-line2); border-bottom-width: 2px; background: var(--aps-bundle-card); color: var(--aps-bundle-mute); }
  &.is-dragging, &.is-dragging * { cursor: grabbing !important; user-select: none; -webkit-user-select: none; }

  & .aps-bundle-top { display: flex; align-items: center; gap: 18px; padding: 12px 20px; border-bottom: 1px solid var(--aps-bundle-line); }
  & .aps-bundle-brand { display: flex; align-items: center; gap: 8px;
    & svg { width: 22px; height: 22px; fill: var(--aps-bundle-accent); stroke: var(--aps-bundle-bg); stroke-width: 1.2; }
    & b { font: italic 600 21px/1 var(--aps-bundle-serif); letter-spacing: -.01em; }
  }
  & .aps-bundle-kick { margin: 0 auto 0 6px; font-size: 13px; font-weight: 600;
    & span { font-weight: 450; color: var(--aps-bundle-mute); }
  }
  & .aps-bundle-tabs { display: none; }
  & .aps-bundle-bag { position: relative; width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--aps-bundle-line2); background: var(--aps-bundle-card); display: grid; place-items: center;
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; }
    & span { position: absolute; top: -3px; right: -4px; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 10px; display: grid; place-items: center; background: var(--aps-bundle-accent); color: white; font: 700 11px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; transition: scale .4s var(--aps-bundle-spring); }
    & span:empty { scale: 0; }
  }

  & .aps-bundle-body { min-height: 0; display: grid; grid-template: "shelf stage sum" minmax(0, 1fr) / minmax(250px, 27%) minmax(0, 1fr) minmax(270px, 28%); }

  /* ── shelf ── */
  & .aps-bundle-shelf { grid-area: shelf; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; border-right: 1px solid var(--aps-bundle-line); }
  & .aps-bundle-cats { position: sticky; top: 0; z-index: 2; display: flex; gap: 5px; padding: 12px 14px 10px; background: color-mix(in oklab, var(--aps-bundle-bg) 92%, transparent); backdrop-filter: blur(8px); overflow-x: auto; scrollbar-width: none;
    & button { flex: none; height: 30px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--aps-bundle-line2); background: none; font-size: 12.5px; font-weight: 550; transition: background .2s, color .2s; }
    & button small { font-size: 11px; opacity: .6; font-variant-numeric: tabular-nums; }
    & [aria-checked="true"] { background: var(--aps-bundle-ink); border-color: var(--aps-bundle-ink); color: var(--aps-bundle-card); }
  }
  & .aps-bundle-goods { list-style: none; margin: 0; padding: 4px 14px 18px; display: grid; grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 10px; }
  & .aps-bundle-good { position: relative; display: grid; gap: 2px; padding: 10px 10px 12px; border-radius: 14px; background: var(--aps-bundle-card); border: 1px solid var(--aps-bundle-line); cursor: grab; touch-action: none; -webkit-user-select: none; user-select: none; transition: translate .4s var(--aps-bundle-soft), box-shadow .3s, border-color .2s;
    @starting-style { opacity: 0; translate: 0 8px; }
    & .aps-bundle-plate { aspect-ratio: 1; border-radius: 50%; margin: 2px 8px 8px; display: grid; place-items: center; background: radial-gradient(circle at 50% 40%, color-mix(in oklab, var(--t) 26%, var(--aps-bundle-card)), color-mix(in oklab, var(--t) 12%, var(--aps-bundle-card)) 70%); }
    & .aps-bundle-plate svg { width: 78%; height: 78%; filter: drop-shadow(0 4px 4px rgb(60 30 20 / .18)); transition: rotate .5s var(--aps-bundle-spring), scale .5s var(--aps-bundle-spring); }
    & b { font-size: 13px; font-weight: 620; line-height: 1.25; text-wrap: balance; }
    & small { font-size: 11.5px; color: var(--aps-bundle-mute); text-wrap: pretty; }
    & .aps-bundle-pr { display: flex; align-items: center; justify-content: space-between; margin-top: 6px; font-weight: 650; font-variant-numeric: tabular-nums; }
    & .aps-bundle-pr button { width: 28px; height: 28px; border-radius: 50%; border: 0; background: var(--aps-bundle-ink); color: var(--aps-bundle-card); display: grid; place-items: center; transition: scale .3s var(--aps-bundle-spring), background .2s; }
    & .aps-bundle-pr button svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
    & .aps-bundle-pr button:hover { background: var(--aps-bundle-accent); scale: 1.08; }
    & .aps-bundle-pr button:disabled { opacity: .3; cursor: not-allowed; scale: 1; background: var(--aps-bundle-ink); }
    & .aps-bundle-in { position: absolute; top: 8px; right: 8px; min-width: 20px; height: 20px; padding: 0 6px; border-radius: 10px; display: grid; place-items: center; background: var(--aps-bundle-accent); color: white; font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums; animation: aps-bundle-pop .5s var(--aps-bundle-spring); }
    &:hover { translate: 0 -2px; box-shadow: 0 12px 24px -16px rgb(60 30 20 / .5); border-color: var(--aps-bundle-line2); }
    &:focus-visible { border-radius: 14px; border-color: var(--aps-bundle-accent); }
    &:hover .aps-bundle-plate svg { rotate: -8deg; scale: 1.06; }
  }

  /* ── stage: the box, top-down ── */
  & .aps-bundle-stage { grid-area: stage; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; display: flex; flex-direction: column; align-items: center; gap: 14px; padding: 16px clamp(14px, 2.4cqi, 30px) 18px;
    background: radial-gradient(70% 60% at 50% 45%, color-mix(in oklab, var(--aps-bundle-kraft) 16%, var(--aps-bundle-bg)), var(--aps-bundle-bg) 75%); }
  & .aps-bundle-sizes { display: flex; gap: 4px; padding: 4px; border-radius: 12px; background: color-mix(in oklab, var(--aps-bundle-ink) 6%, transparent);
    & button { display: grid; justify-items: center; gap: 0; min-width: 92px; padding: 6px 12px; border: 0; border-radius: 9px; background: none; color: var(--aps-bundle-mute); transition: background .3s var(--aps-bundle-ease), color .2s, box-shadow .3s; }
    & button b { font-size: 13px; font-weight: 650; }
    & button small { font-size: 11.5px; font-variant-numeric: tabular-nums; }
    & [aria-checked="true"] { background: var(--aps-bundle-card); color: var(--aps-bundle-ink); box-shadow: 0 1px 3px rgb(60 30 20 / .16); }
  }
  & .aps-bundle-scene { position: relative; width: min(100%, calc(var(--cols, 3) * 136px + 60px)); perspective: 1200px; margin: 4px 0 0; }
  & .aps-bundle-box { position: relative; padding: 16px; border-radius: 10px; transform-style: preserve-3d;
    background: linear-gradient(135deg, color-mix(in oklab, var(--aps-bundle-kraft), white 12%), var(--aps-bundle-kraft) 45%, color-mix(in oklab, var(--aps-bundle-kraft), black 8%));
    box-shadow: inset 0 0 0 1px rgb(80 50 20 / .15), 0 30px 50px -30px rgb(70 40 20 / .55), 0 2px 0 rgb(80 50 20 / .2);
    transition: transform .9s var(--aps-bundle-ease);
    &::before { content: ""; position: absolute; inset: 9px; border-radius: 6px; background:
      repeating-linear-gradient(115deg, rgb(255 255 255 / .0) 0 14px, rgb(255 255 255 / .35) 14px 15px, rgb(255 255 255 / 0) 15px 31px),
      repeating-linear-gradient(32deg, rgb(120 70 60 / .0) 0 22px, rgb(120 70 60 / .06) 22px 23px, rgb(0 0 0 / 0) 23px 41px),
      var(--aps-bundle-tissue); box-shadow: inset 0 3px 8px rgb(80 50 20 / .22); }
  }
  & .aps-bundle-slots { position: relative; display: grid; grid-template-columns: repeat(var(--cols, 3), 1fr); gap: 10px; }
  & .aps-bundle-slot { position: relative; aspect-ratio: 1; -webkit-user-select: none; user-select: none; border-radius: 10px; display: grid; place-items: center; border: 1.5px dashed color-mix(in oklab, var(--aps-bundle-ink) 20%, transparent); background: color-mix(in oklab, var(--aps-bundle-tissue), var(--aps-bundle-kraft) 8%); outline-offset: 2px; transition: border-color .2s, background .25s, scale .35s var(--aps-bundle-soft);
    animation: aps-bundle-slot .5s var(--aps-bundle-soft) calc(var(--i, 0) * 40ms) both;
    & > span { font-size: 22px; font-weight: 300; color: color-mix(in oklab, var(--aps-bundle-ink) 30%, transparent); }
    & .aps-bundle-item { width: 84%; height: 84%; rotate: var(--r, 0deg); filter: drop-shadow(0 5px 5px rgb(70 40 20 / .28)); transition: translate .4s var(--aps-bundle-soft), rotate .4s var(--aps-bundle-soft), filter .3s; animation: aps-bundle-drop .55s var(--aps-bundle-spring) both; }
    &.is-full { border-style: solid; border-color: rgb(80 50 20 / .12); background: color-mix(in oklab, var(--aps-bundle-tissue), white 30%); cursor: grab; touch-action: none; }
    &.is-full:hover .aps-bundle-item { translate: 0 -3px; rotate: calc(var(--r, 0deg) - 3deg); filter: drop-shadow(0 9px 7px rgb(70 40 20 / .28)); }
    &.is-over { border-color: var(--aps-bundle-accent); border-style: solid; background: var(--aps-bundle-tint); scale: 1.04; }
    &.is-held { border-color: var(--aps-bundle-accent); border-style: solid; box-shadow: 0 0 0 4px color-mix(in oklab, var(--aps-bundle-accent) 20%, transparent); }
    &.is-held .aps-bundle-item { translate: 0 -6px; rotate: calc(var(--r, 0deg) + 4deg); filter: drop-shadow(0 14px 10px rgb(70 40 20 / .3)); }
    &.is-src .aps-bundle-item { opacity: .25; }
    &:focus-visible { outline: 2px solid var(--aps-bundle-accent); border-radius: 10px; }
  }
  & .aps-bundle-ghost { position: absolute; z-index: 90; left: 0; top: 0; width: 84px; height: 84px; margin: -42px 0 0 -42px; pointer-events: none; filter: drop-shadow(0 18px 14px rgb(60 30 20 / .35)); rotate: -6deg; scale: 1.08; transition: scale .25s var(--aps-bundle-soft), rotate .25s, opacity .2s;
    &.is-out { scale: .8; opacity: .6; }
    & svg { width: 100%; height: 100%; }
    &.is-fly { transition: none; rotate: none; scale: none; }
  }

  /* lid + ribbon, folded back until the box is closed */
  & .aps-bundle-lid { position: absolute; inset: -6px; border-radius: 12px; transform-origin: 50% 0; transform: rotateX(104deg); opacity: 0; pointer-events: none; overflow: hidden;
    background: linear-gradient(160deg, color-mix(in oklab, var(--aps-bundle-kraft), white 18%), var(--aps-bundle-kraft) 50%, color-mix(in oklab, var(--aps-bundle-kraft), black 10%));
    box-shadow: inset 0 0 0 1px rgb(80 50 20 / .2), 0 30px 40px -24px rgb(70 40 20 / .6);
    transition: transform .8s var(--aps-bundle-ease), opacity .2s .6s;
    & > b { position: absolute; left: 50%; bottom: 14%; translate: -50% 0; font: italic 600 clamp(16px, 3cqi, 22px) var(--aps-bundle-serif); color: rgb(70 40 20 / .5); letter-spacing: .02em; }
  }
  & .aps-bundle-rib { position: absolute; background: linear-gradient(90deg, color-mix(in oklab, var(--aps-bundle-rib), black 12%), var(--aps-bundle-rib) 30%, color-mix(in oklab, var(--aps-bundle-rib), white 18%) 50%, var(--aps-bundle-rib) 70%, color-mix(in oklab, var(--aps-bundle-rib), black 12%)); transition: clip-path .6s var(--aps-bundle-ease) .75s; }
  & .aps-bundle-rib-v { left: 50%; top: 0; bottom: 0; width: 26px; translate: -50% 0; clip-path: inset(50% 0 50% 0); }
  & .aps-bundle-rib-h { top: 44%; left: 0; right: 0; height: 26px; background: linear-gradient(180deg, color-mix(in oklab, var(--aps-bundle-rib), black 12%), var(--aps-bundle-rib) 30%, color-mix(in oklab, var(--aps-bundle-rib), white 18%) 50%, var(--aps-bundle-rib) 70%, color-mix(in oklab, var(--aps-bundle-rib), black 12%)); clip-path: inset(0 50% 0 50%); }
  & .aps-bundle-bow { position: absolute; left: 50%; top: calc(44% + 13px); width: 34%; translate: -50% -50%; scale: 0; transition: scale .7s var(--aps-bundle-spring) 1.2s;
    & path { fill: var(--aps-bundle-rib); stroke: color-mix(in oklab, var(--aps-bundle-rib), black 20%); stroke-width: 1; }
    & circle { fill: color-mix(in oklab, var(--aps-bundle-rib), black 10%); }
  }
  & .aps-bundle-tag { position: absolute; z-index: 3; right: -6px; bottom: -18px; width: 168px; padding: 10px 12px 12px 22px; border-radius: 4px 8px 8px 4px; background: var(--aps-bundle-card); box-shadow: 0 10px 22px -12px rgb(60 30 20 / .5); rotate: 4deg; transform-origin: 0 50%; opacity: 0; scale: .8; transition: opacity .3s 1.4s, scale .6s var(--aps-bundle-spring) 1.4s;
    & i { position: absolute; left: 8px; top: 50%; width: 7px; height: 7px; margin-top: -3.5px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--aps-bundle-line2); }
    & p { margin: 0; font: italic 13px/1.35 var(--aps-bundle-serif); text-wrap: pretty; overflow-wrap: anywhere; }
  }
  &.is-closed .aps-bundle-lid { transform: rotateX(0deg); opacity: 1; transition: transform .8s var(--aps-bundle-ease), opacity .05s; }
  &.is-closed .aps-bundle-rib-v { clip-path: inset(0 0 0 0); }
  &.is-closed .aps-bundle-rib-h { clip-path: inset(0 0 0 0); }
  &.is-closed .aps-bundle-bow { scale: 1; }
  &.is-closed .aps-bundle-tag { opacity: 1; scale: 1; }
  &.is-closed .aps-bundle-box { transform: rotateX(8deg); }
  & .aps-bundle-hint { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 14px; margin: 12px 0 0; font-size: 11.5px; color: var(--aps-bundle-mute);
    & span { display: inline-flex; align-items: center; gap: 3px; }
  }

  /* ── summary ── */
  & .aps-bundle-sum { grid-area: sum; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 16px 18px 20px; border-left: 1px solid var(--aps-bundle-line); background: var(--aps-bundle-card); display: flex; flex-direction: column; gap: 14px; }
  & .aps-bundle-tier { display: grid; grid-template-columns: 76px 1fr; gap: 14px; align-items: center;
    & h2 { margin: 0 0 6px; font-size: 14.5px; font-weight: 650; line-height: 1.3; text-wrap: balance; }
  }
  & .aps-bundle-ring { --aps-bundle-fill: 0; position: relative; width: 76px; height: 76px; border-radius: 50%; display: grid; place-content: center; text-align: center; transition: --aps-bundle-fill .9s var(--aps-bundle-soft);
    background: radial-gradient(closest-side, var(--aps-bundle-card) 78%, transparent 79%), conic-gradient(var(--aps-bundle-accent) calc(var(--aps-bundle-fill) * 1turn), var(--aps-bundle-line) 0);
    & b { font-size: 21px; font-weight: 750; line-height: 1; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
    & span { font-size: 10.5px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--aps-bundle-mute); }
  }
  & .aps-bundle-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 3px; font-size: 12px; color: var(--aps-bundle-mute); font-variant-numeric: tabular-nums;
    & li { display: flex; align-items: center; gap: 7px; }
    & li::before { content: ""; width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid var(--aps-bundle-line2); }
    & li.is-on { color: var(--aps-bundle-ink); font-weight: 600; }
    & li.is-on::before { border-color: var(--aps-bundle-accent); background: var(--aps-bundle-accent) radial-gradient(circle, white 0 2px, transparent 2.5px); }
  }
  & .aps-bundle-picked { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; font-size: 13px;
    & li { display: grid; grid-template-columns: 30px 1fr auto 26px; align-items: center; gap: 10px; animation: aps-bundle-row .4s var(--aps-bundle-soft) both; }
    & li > svg { width: 30px; height: 30px; }
    & li > p { margin: 0; min-width: 0; line-height: 1.25; }
    & li small { display: block; font-size: 11.5px; color: var(--aps-bundle-mute); font-variant-numeric: tabular-nums; }
    & span { font-variant-numeric: tabular-nums; font-weight: 600; }
    & li button { width: 26px; height: 26px; border-radius: 50%; border: 1px solid var(--aps-bundle-line2); background: none; display: grid; place-items: center; color: var(--aps-bundle-mute); transition: background .2s, color .2s, border-color .2s; }
    & li button svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
    & li button:hover { background: var(--aps-bundle-ink); border-color: var(--aps-bundle-ink); color: var(--aps-bundle-card); }
    & li button:disabled { opacity: .35; pointer-events: none; }
    & .is-empty { display: block; color: var(--aps-bundle-mute); text-wrap: pretty; animation: none; }
  }
  & .aps-bundle-ribbons { margin: 0; padding: 0; border: 0;
    & legend { padding: 0; margin-bottom: 6px; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--aps-bundle-mute); }
    & div { display: flex; gap: 8px; }
    & label { position: relative; width: 30px; height: 30px; border-radius: 50%; cursor: pointer; background: var(--c); box-shadow: inset 0 -4px 6px rgb(0 0 0 / .18); transition: scale .35s var(--aps-bundle-spring); }
    & label:hover { scale: 1.1; }
    & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
    & label:has(:checked) { box-shadow: inset 0 -4px 6px rgb(0 0 0 / .18), 0 0 0 2px var(--aps-bundle-card), 0 0 0 4px var(--aps-bundle-ink); }
    & label:has(:focus-visible) { outline: 2px solid var(--aps-bundle-accent); outline-offset: 5px; }
  }
  & .aps-bundle-note { display: grid; gap: 6px;
    & > span { display: flex; justify-content: space-between; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--aps-bundle-mute); }
    & em { font-style: normal; letter-spacing: 0; font-variant-numeric: tabular-nums; }
    & textarea { resize: none; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--aps-bundle-line2); background: var(--aps-bundle-bg); font: italic 14px/1.4 var(--aps-bundle-serif); outline: none; transition: border-color .2s, box-shadow .2s; }
    & textarea:focus { border-color: var(--aps-bundle-ink); box-shadow: 0 0 0 3px color-mix(in oklab, var(--aps-bundle-ink) 8%, transparent); }
  }
  & .aps-bundle-tot { display: grid; grid-template-columns: 1fr auto; gap: 6px 12px; margin: 0; padding-top: 12px; border-top: 1px solid var(--aps-bundle-line); font-size: 13px;
    & dt { color: var(--aps-bundle-mute); }
