  sachet: '<path d="M25 44Q21 88 32 88h36q11 0 7-44Z"' + F(mx('black', 18)) + '/><path d="M25 42Q21 86 32 86h36q11 0 7-44Z"' + F(T) + '/><path d="M30 42 24 18q10 6 13 4t13-6q8 6 13 6t13-4l-6 24Z"' + F(mx('white', 18)) + '/><rect x="27" y="37" width="46" height="7" rx="3.5"' + F(CREAM) + '/><path d="M50 52v26M50 58l-5-4m5 4 5-4m-5 10-5-4m5 4 5-4m-5 10-5-4m5 4 5-4"' + S_(mx('black', 35), 1.6) + '/>',
