const MINUS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h12"/></svg>';

/* ── state ── */
let seq = 0;
const piece = pid => ({ pid, u: 'p' + (++seq), r: Math.round(Math.random() * 14 - 7) });
