function totals() {
  const items = S.slots.filter(Boolean), n = items.length;
  const sub = items.reduce((s, x) => s + P[x.pid].p, 0);
  let pct = 0; for (const [k, p] of TIERS) if (n >= k) pct = p;
  const save = Math.round(sub * pct) / 100, box = sizeOf().p;
