}
const listNames = arr => { const ns = arr.map(x => P[x.pid].n); return ns.length < 2 ? ns[0] : ns.slice(0, -1).join(', ') + ' and ' + ns[ns.length - 1]; };

/* ── elements ── */
const catsEl = $('.aps-bundle-cats'), goodsEl = $('.aps-bundle-goods'), sizesEl = $('.aps-bundle-sizes');
