  const next = Array(z.cap).fill(null), over = [], out = [];
  S.slots.forEach((x, i) => { if (!x) return; if (i < z.cap) next[i] = x; else over.push(x); });
  for (const x of over) { const e = next.indexOf(null); if (e < 0) out.push(x); else next[e] = x; }
  S.size = k; S.slots = next; S.closed = false;
  if (held >= 0) held = -1;
