/* ── slot keyboard: arrows roam, Space lifts and drops, arrows carry a lifted piece, Delete takes out, Escape puts it back ── */
slotsEl.addEventListener('keydown', e => {
  const s = e.target.closest('.aps-bundle-slot'); if (!s) return;
  const i = +s.dataset.i, z = sizeOf();
  const d = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -z.cols, ArrowDown: z.cols }[e.key];
